'记账方向：借 6200（费用）＋ 借 1160（进项税额）→ 贷 2110（应付账款）。这是支出，不是收入。' =>
  'Entry: Dr 6200 (expense) + Dr 1160 (input tax) → Cr 2110 (trade payables). This is an expense, not revenue.',
'你开给客户的发票记在这里：借 应收／合同资产，贷 收入。供应商开给你的发票（支出）请用「新建采购发票」。' =>
  'Invoices you issue to customers go here: Dr receivables / contract assets, Cr revenue. For supplier invoices (expenses) use “New Purchase Bill”.',
'供应商开给你的发票记在这里：借 成本／费用 ＋ 进项税额，贷 应付账款。你自己开给客户的发票请用「新建销售发票」（那是收入）。' =>
  'Supplier invoices go here: Dr cost / expense + input tax, Cr trade payables. For invoices you issue, use “New Sales Invoice” (that is revenue).',
'先分清方向：收到的是支出，开出的是收入' => 'Check the direction first: received = expense, issued = revenue',
'（你开给客户）→ 借 应收/合同资产，贷 收入 —— 这才是收入。' =>
  '(issued to customers) → Dr receivables / contract assets, Cr revenue — this is revenue.',
'（供应商开给你）→ 借 成本/费用 ＋ 进项税额，贷 应付账款 —— 这是支出。' =>
  '(received from suppliers) → Dr cost / expense + input tax, Cr trade payables — this is an expense.',
'上传发票（PDF / 图片 / 文本）— 默认按「我收到的发票（支出）」处理' =>
  'Upload an invoice (PDF / image / text) — treated as “invoice I received” (expense) by default',
'或直接粘贴发票文字' => 'Or paste the invoice text',
'发票智能识别' => 'Invoice Extraction', '识别结果只作建议，须人工确认后才可入账' =>
  'Extraction results are suggestions only; human confirmation is required before posting',
'上传即计算 SHA-256 并写入审计日志，保存 7 年' =>
  'SHA-256 is computed on upload and written to the audit log; retained for 7 years',
'由确定性代码计算' => 'Computed by deterministic code',
