'企业规模' => 'Entity Size', '按 HKAS 1 格式列报；税项按利得税计算表确认后入账，未确认前不预估' =>
  'Presented in accordance with HKAS 1; tax is booked only after the profits tax computation is confirmed, never estimated',
'本财务报表按《香港财务报告准则》(HKFRS) 编制。' => 'These financial statements are prepared in accordance with HKFRS.',
'会计记录采用权责发生制；不同币种的金额不直接相加，折算后方可汇总。' =>
  'The books are kept on an accrual basis; amounts in different currencies are not added directly and are translated before aggregation.',
'金额单位为港元（HKD），除另有注明外均四舍五入至小数点后两位。' =>
  'Amounts are stated in Hong Kong Dollars (HKD) and, unless stated otherwise, rounded to two decimal places.',
'收入：按 HKFRS 15 五步法确认，规则见 hkfrs15 规则文件。' =>
  'Revenue: recognised under the HKFRS 15 five-step model; the rules are defined in the hkfrs15 rule file.',
'外币折算：按 HKAS 21，货币性项目于期末按即期汇率重估，差额计入损益。' =>
  'Foreign currency: under HKAS 21, monetary items are retranslated at the closing rate, with differences taken to profit or loss.',
