  "你开给客户的发票记在这里：借 应收／合同资产，贷 收入。 供应商开给你的发票（支出）请用「新建采购发票」。" => "Invoices you issue to customers: Dr Receivables / Contract asset, Cr Revenue. For invoices suppliers issue to you (expenses), use “New Purchase Invoice”.",
  "供应商开给你的发票记在这里：借 成本／费用 ＋ 进项税额，贷 应付账款。 你自己开给客户的发票请用「新建销售发票」（那是收入）。" => "Invoices suppliers issue to you: Dr Cost / Expense + input tax, Cr Payables. For invoices you issue to customers, use “New Sales Invoice” (that is revenue).",
  "已发生分录的科目不允许停用；有启用中子科目的父科目须先停用子科目。 停用只影响新分录的可选范围，不影响历史账。" => "An account with posted entries cannot be deactivated; a parent with active sub-accounts must have them deactivated first. Deactivation only affects selectable accounts for new entries, not historical books.",
  "（含扫描件，自动 OCR）。 上限 20MB。上传后先出预览，确认无误再导入。" => " (scans included, OCR automatic). Max 20MB. A preview is shown before importing.",
  "停用只影响新分录的可选范围，不影响历史账。" => "Deactivation only affects selectable accounts for new entries, not historical books.",
  "Purchase Bills (供应商开给我 — 支出)" => "Purchase Bills (issued to me by suppliers — expenses)",
  "识别合同 → 识别履约义务 → 确定交易价格 → 分摊 → 履行时确认收入。 合同资产／合同负债／应收按 HKFRS 15.105-109 三方划分。" => "Identify contract → identify obligations → determine price → allocate → recognise on satisfaction. Contract assets, contract liabilities and receivables are split per HKFRS 15.105-109.",
  "期末现金必须与资产负债表现金一致" => "Closing cash must agree with the cash balance in the statement of financial position",
  "按 HKAS 1 格式列报；税项按利得税计算表确认后入账，未确认前不预估" => "Presented under HKAS 1; tax is recognised per the profits tax computation and not accrued before confirmation",
