'确认对账' => 'Confirm reconciliation',
'确认建单' => 'Create document',
'确认批量记账' => 'Post them',

'确认转发票' => 'Convert',
'确认过账' => 'Post it',
'确认锁账' => 'Lock it',
'确认修改两级制资格？' => 'Change the two-tiered status?',
'确认已完成外币重估？' => 'Confirm the FX revaluation is done?',
'确认批量记账？' => 'Post the selected drafts in one batch?',
'确认按这条规则建单？' => 'Create a document from this rule?',
'确认现在跑一次固化？' => 'Run the learning job now?',
'确认记账？这张单据会立即写入总账。' => 'Post this document? It goes into the ledger immediately.',
'确认转成销售发票？' => 'Convert this quotation into an invoice?',
'确认过账这张贷记单？' => 'Post this credit note?',
'确认这些单据已经对账？' => 'Confirm these documents are reconciled?',
'确认锁定期间？' => 'Lock this period?',
'会在「下次执行日」生成一张草稿单据，下次执行日往后推一期。草稿仍需复核与记账才进总账。' => 'A draft is created on the next run date and that date moves forward one period. The draft still needs review and posting before it reaches the ledger.',
'会按报价单明细生成一张销售发票草稿，报价单标记为「已转发票」。发票仍需上传原始凭证、复核、记账后才进总账。' => 'A draft sales invoice is created from the quotation lines and the quotation is marked as converted. The invoice still needs its source document, review and posting before it reaches the ledger.',
'会生成一张红字凭证：客户贷记 借收入 / 贷应收；供应商贷记 借应付 / 贷费用。过账后不可修改，也不能删除，只能再开一张反向贷记单。' => 'A reversing entry is written: customer credit debits revenue and credits receivables; vendor credit debits payables and credits expenses. It cannot be edited or deleted afterwards — only another reversing credit note can offset it.',
'先降级近期被推翻的规则，再把达到门槛（≥5 次一致、≥80% 采纳）的偏好固化成规则。固化只影响填写习惯与默认值，不改变任何判断口径或税率。每次动作都写入审计链。' => 'Rules that were recently overruled are demoted first, then preferences that reach the threshold (5 consistent uses, 80% adoption) are locked in. Learning only affects filling habits and defaults — never a judgement, a tax rate or a policy. Every action goes into the audit chain.',
'勾选的每张草稿都会立即写入总账。记账后不可修改或删除，只能冲销。' => 'Every selected draft goes into the ledger immediately. Once posted it cannot be edited or deleted, only reversed.',
'将依次执行：提交复核 → 批准 → 记账。记账后不可修改或删除，只能冲销；作废与冲销同样需要再次确认。' => 'Runs submit for review → approve → post. Once posted it cannot be edited or deleted, only reversed; voiding and reversing also ask for confirmation.',
'确认后相关分录会被标记为已对账并纳入财务报表。金额不会变动；若对账有误，需由会计另行调整。' => 'The related entries are marked reconciled and included in the financial statements. Amounts do not change; if the reconciliation is wrong, the accountant must adjust separately.',
'这一步只记录月结进度，不会自动生成重估分录。外币余额的重估请先到「期末重估」执行。' => 'This only records closing progress; it does not write revaluation entries. Run the FX revaluation on the revaluation page first.',
'这会改变本年度应缴税额的计算方式，并写入审计链。资格认定错误会直接导致报税表金额错误。' => 'This changes how the tax payable for this year is computed and is written to the audit chain. Getting it wrong makes the tax return wrong.',
'锁定后该期间不能再写入任何分录（数据库触发器强制）。解锁需要另行操作并留痕。请确认本期银行对账、应收应付、汇率、重估、计提都已处理完。' => 'Once locked, no entry can be written to that period (enforced by a database trigger). Unlocking is a separate, logged action. Make sure bank reconciliation, AR/AP, FX rates, revaluation and accruals are all done.',
'提交记账' => 'Post',
