'个' => '',
'三个岗位 + 复核守门人 + 三参谋 · 工具只读或只提案 · 没有任何智能体能记账' => 'Three roles + a review gatekeeper + three advisors · tools are read-only or propose-only · no agent can post an entry',
'记账、作废、冲销、锁账、对外发送——这五件事没有任何智能体可以执行，必须由人工在标准界面确认后，由确定性代码完成。propose_document 只写「待确认提案」，人点了「确认导入」才建单；提案被拒绝就什么都不写。' => 'Posting, voiding, reversing, locking a period and sending something out — no agent can do any of these; a person confirms on the screen and deterministic code carries it out. propose_document only writes a pending proposal: the document is created when a person clicks import, and nothing is written if they discard it.',

