// ---- 执行级工具 ----
'可执行' => 'Can write',
'会计与出纳可执行写操作' => 'The accountant and cashier can write',
'按当前设定，会计与出纳智能体可以直接建单、记账、冲销、收付款核销、银行匹配、锁账；每一次都以 agent:<岗位> 记入审计链。指令台可切换为「只提案」。' => 'As configured, the accountant and cashier agents can create documents, post entries, reverse them, settle receipts and payments, confirm bank matches and lock periods. Every action is written to the audit chain as agent:<role>. The console can be switched back to propose-only.',
'无执行级工具' => 'Tools by permission level',

// ---- 执行权限说明 ----
'说一句话就行。会计与出纳可以直接建单、记账、冲销、收付款；每笔都会在下面列出单号与凭证号，并记入审计链。' => 'Just say it. The accountant and cashier can create documents, post entries, reverse them and settle cash directly; every action lists its document or entry number below and goes into the audit chain.',
'个可执行' => 'can write',

// ---- 写权限说明 ----
'三个岗位 + 复核守门人 + 三参谋 · 会计与出纳可执行写操作 · 每笔都记 agent:<岗位>' => 'Three roles + a review gatekeeper + three advisors · the accountant and cashier can write · every action logged as agent:<role>',
'标「Can write」的 9 个工具会直接写账套，只有会计与出纳能用，每笔以 agent:‹岗位› 记入审计链（带上发起人）。propose_document 是「只提案」模式下的路径：只写待确认提案，人点确认才建单。指令台可一键切换「可直接执行 / 只提案」。' => 'The 9 tools marked “Can write” write to the ledger directly and are available only to the accountant and cashier. Every action is recorded as agent:<role>, with the requesting user. propose_document is the propose-only path: it writes a pending proposal and creates the document only when a person confirms. The console switches between the two in one click.',

// ---- 岗位边界 ----
'会计管账不管钱，出纳管钱不管账' => 'The accountant keeps the books, the cashier handles the money',
'会计可建单、记分录、记账、冲销、锁账，但不登记收付款、不确认银行匹配；出纳可登记收付款、核销、确认银行匹配、建单，但不做分录、不记账、不冲销、不锁账。每次执行以 agent:<岗位> 记入审计链。指令台可切换为「只提案」。' => 'The accountant can create documents, write journal entries, post, reverse and lock periods, but never records receipts or payments or confirms bank matches. The cashier can record receipts and payments, settle documents, confirm bank matches and create documents, but never writes journal entries, posts, reverses or locks periods. Every action is recorded as agent:<role>. The console can switch to propose-only.',

// ---- 岗位边界（页头） ----
'三个岗位 + 复核守门人 + 三参谋 · 会计管账不管钱、出纳管钱不管账 · 每笔都记 agent:<岗位>' => 'Three roles + a review gatekeeper + three advisors · the accountant keeps the books, the cashier handles the money · every action logged as agent:<role>',

// ---- 单据方向与对账单拦截 ----
'识别依据' => 'Why this direction',
'这是一份银行对账单，不是发票/收据。请到「流水导入」导入，系统会按交易逐条识别并给出匹配建议；把它当发票识别只会得到错误的金额与对象。' => 'This is a bank statement, not an invoice or receipt. Import it on the bank import page — the system reads it transaction by transaction and suggests matches. Treating it as an invoice only produces wrong amounts and a wrong counterparty.',
'这是银行对账单，不是发票/收据；请用「流水导入」处理，按交易逐条识别比对。' => 'This is a bank statement, not an invoice or receipt; use bank import, which reads it transaction by transaction.',
'去导入银行流水' => 'Go to bank import',

