'今天的待办：今天该做什么，从这里开始。' => 'Today\'s queue: what needs doing today. Start here.',
'先看「待处理」：到期单据、待复核、未核销的对账单。' => 'Check the pending list: due documents, reviews waiting, unmatched bank lines.',
'每个数字都能点，点进去就是那张单据。' => 'Every number is clickable; it opens that document.',
'不确定要做什么，就切到 AI 模式用一句话说清楚。' => 'If you are unsure, switch to AI mode and just say what you need.',
'经营快照：收入、毛利、现金、应收应付和差异桥。' => 'Business snapshot: revenue, gross profit, cash, receivables, payables, variance bridge.',
'期间在右上角切换，默认本月。' => 'Switch the period at the top right; defaults to this month.',
'差异桥回答「为什么比上月多/少」，点到科目层。' => 'The bridge explains why this month differs from last, down to account level.',
'报表要 PDF 就去报表中心，不要在仪表板里找导出。' => 'For report PDFs go to the report centre, not here.',
'销售发票列表：开给客户的单据，过账后才进收入。' => 'Sales invoices: documents you issue; only posted ones hit revenue.',
'点发票号看详情：明细、附件、复核状态。' => 'Click the invoice number for lines, attachments and review status.',
'草稿可以「提交复核」；复核人批准后才可以记账。' => 'Drafts can be submitted for review; the reviewer must approve before posting.',
'开错单价用贷记单冲减，别改已过账的发票。' => 'Wrong price? Issue a credit note. Do not edit a posted invoice.',
'新建销售发票：先填客户与明细，系统自己算金额。' => 'New sales invoice: enter customer and lines; the system does the arithmetic.',
'金额由「数量 × 单价」算，不由你手填总额。' => 'Amount is quantity × unit price — you never type the total.',
'上传原始凭证后再提交复核，凭证是复核的依据。' => 'Attach the source document before submitting for review.',
'外币单据要填汇率或港币金额，不要空着。' => 'For foreign currency, enter the rate or the HKD amount; do not leave it blank.',
'一张销售发票的全部内容：明细、附件、凭证、复核与人。' => 'One sales invoice in full: lines, attachments, journal entry, review trail.',
'流程：提交复核 → 批准 → 记账。' => 'Flow: submit for review → approve → post.',
'过账后不可改，只能冲销或开贷记单。' => 'Once posted it is locked; use a reversal or a credit note.',
'「原始凭证」必须有，否则审计链上这条是空的。' => 'The source document is required, otherwise the audit chain has a gap.',
'客户档案：开票对象与信用条件。' => 'Customer file: who you invoice and on what terms.',
'名称一定要和合同一致，否则对账对不上。' => 'The name must match the contract, otherwise reconciliation fails.',
'关联方要勾上，年末披露要用。' => 'Tick related party — needed for year-end disclosure.',
'停用客户不会删历史单据。' => 'Disabling a customer keeps its documents.',
'采购发票列表：供应商开给你的单据，过账后才进成本/费用。' => 'Purchase bills: documents your suppliers issue; only posted ones hit cost/expense.',
'点单号看详情，可上传原件作为凭证。' => 'Click the number for detail; attach the supplier original.',
'到期日决定「待付款」排序。' => 'Due date drives the payables ordering.',
'重复入账会被拦：同一天同金额同供应商会提示。' => 'Duplicate entry is blocked: same day, amount and vendor raises a flag.',
'一张采购账单：金额、明细、原始凭证、复核状态。' => 'One purchase bill: amount, lines, source document, review status.',
'先上传供应商原件，再提交复核。' => 'Attach the supplier original first, then submit for review.',
