'外币要填汇率，否则过账会被拦。' => 'Foreign currency needs a rate, otherwise posting is blocked.',
'费用单：没有正式发票的小额支出，也要有凭证。' => 'Expense claims: small spends without a formal invoice, still need evidence.',
'点单号看详情与附件。' => 'Click the number for detail and attachments.',
'费用科目决定进哪一行损益。' => 'The expense account decides which P&L line it lands on.',
'金额小的也建议传收据，否则审计时无法解释。' => 'Even small amounts should have a receipt, otherwise audit cannot explain it.',
'新建费用：差旅、办公、银行手续费这类。' => 'New expense: travel, office, bank charges and the like.',
