'常用科目记在这里，建单时会自动建议。' => 'The usual account is stored here and suggested when creating documents.',
'报价单：先报价后开票，报价不进总账。' => 'Quotes: quote first, invoice later. A quote never touches the ledger.',
'发出 → 客户接受 → 转发票（一键生成销售发票草稿）。' => 'Send → customer accepts → convert to invoice (creates a draft invoice).',
'只有转成发票并通过复核，才影响收入。' => 'Revenue is affected only once the invoice is posted.',
'过期报价会自动标失效，可以复制重发。' => 'Expired quotes are marked automatically; copy one to resend.',
'贷记单：退货、折让、开票错误的红字单据。' => 'Credit notes: the red document for returns, allowances and billing errors.',
'客户方向：借收入 / 贷应收；供应商方向：借应付 / 贷费用。' => 'Customer: Dr revenue / Cr receivables. Vendor: Dr payables / Cr expense.',
'过账后不能改，只能再开一张反向的。' => 'Once posted it cannot be edited; issue a reversing credit note instead.',
'它只减金额，不改变原发票的已核销额。' => 'It only reduces the amount; it does not change what is already settled.',
'循环交易：租金、订阅这类每月重复的单据。' => 'Recurring entries: rent, subscriptions — documents that repeat monthly.',
'设好频率与开始日，到期自动建草稿（可选自动记账）。' => 'Set frequency and start date; drafts are created when due (optional auto-post).',
'暂停不会删历史，只是不再生成。' => 'Pausing keeps the history, it only stops new documents.',
'金额变了就改规则，不要手工改已生成的单。' => 'If the amount changes, edit the rule — do not hand-edit generated documents.',
'收款核销：客户付钱后，把收款匹配到发票。' => 'Receipts: match customer payments to invoices.',
'先选收款账户和金额，再勾要核销的发票。' => 'Pick the bank account and amount, then tick the invoices to settle.',
'外币收款会产生汇兑差额，系统自己算。' => 'Foreign currency receipts create an FX difference; the system computes it.',
'同一笔收款可以对多张发票。' => 'One receipt can settle several invoices.',
'付款核销：付供应商钱，匹配到采购账单。' => 'Payments: match what you paid to purchase bills.',
'按「未结清金额」勾选，部分付款也可以。' => 'Tick by outstanding amount; partial payment is fine.',
'跨币种支付会生成汇兑差额分录。' => 'Cross-currency payment creates an FX difference entry.',
'付错对象不要删，做冲销。' => 'Paid the wrong party? Reverse it, do not delete.',
'一张收付款的全部内容：账户、核销了哪些单、生成的分录。' => 'One payment in full: account, what it settled, the journal entry.',
'核销明细决定哪些单据变成已结清。' => 'The allocation lines decide which documents become settled.',
'汇兑差额单独列示，会计入损益。' => 'FX differences are shown separately and hit profit or loss.',
'银行账户：账套里的钱放在哪几个户。' => 'Bank accounts: where the money sits.',
'每个账户对应一个科目，余额自动汇总。' => 'Each account maps to one ledger account; balances roll up.',
'新增账户会计入总账科目表。' => 'Adding an account also creates the ledger account.',
'信用卡也在这里建（余额为负）。' => 'Credit cards are created here too (negative balance).',
'流水导入：把银行月结单导进来变成待对账的流水。' => 'Statement import: turn a bank statement into lines awaiting reconciliation.',
'支持 PDF 与 CSV；同一份文件不会重复导入。' => 'PDF and CSV are supported; the same file is never imported twice.',
'导入会做借贷合计与余额勾稽，不平会拦下。' => 'Import checks debit/credit totals and the balance; an imbalance is refused.',
'导入之后去「对账工作区」逐笔匹配。' => 'After importing, match line by line in the reconciliation desk.',
'对账工作区：把银行流水和发票/账单对上。' => 'Reconciliation desk: match bank lines to invoices and bills.',
'系统按金额、日期、对手方打分，高置信自动核销。' => 'The system scores by amount, date and counterparty; high confidence auto-settles.',
'剩下的逐笔确认，不确定就不要硬对。' => 'Confirm the rest one by one; do not force a match you are unsure about.',
'对不上的流水会留在未匹配里，可以挂手续费。' => 'Unmatched lines stay in the list; you can book them as bank charges.',
'会计科目：账套的骨架，决定报表怎么分类。' => 'Chart of accounts: the skeleton of the ledger and of every report.',
'科目被用过之后不要改代码，报表会对不上。' => 'Do not change a code once it is used — reports will break.',
'新增科目要选对报表项目（FS line item）。' => 'When adding an account, pick the right FS line item.',
'科目树是分层的，父子关系影响汇总。' => 'The tree is hierarchical; parent/child affects totals.',
'日记账：所有凭证，包括单据生成的和手工录入的。' => 'Journal: every entry, whether generated by a document or entered by hand.',
'点分录号看借贷明细。' => 'Click the entry number for the debit and credit lines.',
'记错了用「冲销」生成反向分录，不要删。' => 'Wrong entry? Use reversal to create the opposite entry; do not delete.',
'只有草稿能改；过账后写死在审计链上。' => 'Only drafts can be edited; posted entries are sealed in the audit chain.',
'手工分录：调账、计提、更正用。' => 'Manual entry: for adjustments, accruals and corrections.',
'借贷必须平，不平不让保存。' => 'Debits must equal credits; it will not save otherwise.',
'摘要要写清为什么调这笔。' => 'The description must say why this adjustment was made.',
'谨慎使用：手工分录没有单据支撑，审计会问。' => 'Use sparingly: manual entries have no supporting document, audit will ask.',
'期末重估：外币账户按期末汇率重估。' => 'Period-end revaluation: foreign currency balances at the closing rate.',
'先维护汇率，再跑重估。' => 'Maintain the rate first, then run the revaluation.',
'重估生成的分录可以冲销。' => 'The generated entry can be reversed.',
'每期只跑一次，跑两次会重复计提。' => 'Run once per period; running twice double-counts.',
'汇率维护：外币折算的依据。' => 'FX rates: the basis for translating foreign currency.',
'按币种与日期录，系统取最接近的日期。' => 'Enter by currency and date; the system picks the nearest date.',
'没有汇率的外币单据过不了账。' => 'A foreign document cannot post without a rate.',
'录错了改当天那条，不要新增重复日期。' => 'Wrong rate? Fix that day\'s row, do not add a duplicate date.',
'期间锁定：锁住已结账的月份，防止事后改动。' => 'Period lock: seal a closed month against later changes.',
'锁之前先确认该期的报表已经出完。' => 'Confirm the period\'s reports are final before locking.',
'锁定后该期间不能新记账、不能冲销。' => 'Once locked you cannot post or reverse in that period.',
'要改只能先解锁（会留在审计日志上）。' => 'To change it you must unlock first, which is written to the audit log.',
'待复核：所有需要人看一眼才能往下走的单据。' => 'Review queue: everything that needs a human look before moving on.',
'红色是阻断项，不处理就过不了账。' => 'Red means blocking — posting stays blocked until it is handled.',
'处理完会从列表消失。' => 'Handled items disappear from this list.',
'阻断原因看不懂就去单据详情看校验明细。' => 'If the reason is unclear, open the document and read the validation detail.',
'核销工作台：一张表看完谁欠谁、哪些还没对上。' => 'Allocation workbench: one table showing who owes whom and what is unmatched.',
'按往来单位筛选，找具体那一笔。' => 'Filter by counterparty to find that one item.',
'点金额进单据，直接核销。' => 'Click an amount to open the document and settle it.',
'账龄和未结清金额都按单据日算。' => 'Aging and outstanding amounts are measured from the document date.',
'月结：把当月账结掉，出报表，锁期间。' => 'Month-end close: close the month, produce reports, lock the period.',
'顺序：核对 → 重估 → 出报表 → 锁定期间。' => 'Order: check → revalue → reports → lock the period.',
'结账前先看「待复核」清干净没有。' => 'Before closing, make sure the review queue is empty.',
'锁了之后再改要走解锁流程。' => 'Changes after locking go through the unlock flow.',
'利得税：按本年利润算应缴税，附两级制判断。' => 'Profits tax: the tax due on this year\'s profit, with the two-tier test.',
'数字来自已过账分录，不是估算。' => 'The numbers come from posted entries, not from estimates.',
