'报表语言跟随右上角的界面语言。' => 'Report language follows the interface language at the top right.',
'审计日志：每一条写操作都在这里，哈希链串起来。' => 'Audit log: every write operation, chained with hashes.',
'按时间倒序，可以按人/对象筛。' => 'Newest first; filter by person or object.',
'链校验通过 = 中间没人改过数据。' => 'Chain verified means nobody altered the data behind your back.',
