    // Page labels and messages
    '完成' => 'Completed',
    '贷记单已保存并过账（红字凭证' => 'Credit note saved and posted (reversing entry',
    '贷记单已保存为草稿，过账失败：' => 'Credit note saved as draft; posting failed: ',
