    '供应商档案未登记邮箱，请手工填写；如需长期使用可在「供应商」页补充' => 'No email is saved for this vendor. Enter it manually, or add it on the Vendors page for future use',
    '填写邮箱授权码' => 'Enter the email authorization code',
