    '这张凭证没有附件' => 'This voucher has no attachments',
    '编辑订单' => 'Edit order',
    '收货记录' => 'Goods receipts',
    '编辑' => 'Edit',
    '按订单转成销售发票？' => 'Convert this order to a sales invoice?',
    '按订单转成账单？' => 'Convert this order to a bill?',
    '会按订单明细生成一张草稿，仍需上传凭证、复核、记账后才进总账。' => 'A draft will be created from the order lines. Upload supporting documents, review, and post it before it enters the general ledger.',
    '转账单' => 'Convert to bill',
    '供应商名称 *' => 'Supplier name *',
    '已下单（未履行可编辑）' => 'Ordered (editable until fulfilled)',
    '报价单编号' => 'Quote no.',
    '自动记账未完成' => 'Auto-posting incomplete',
    '会在「下次执行日」生成一张草稿单据，下次执行日往后推一期。' => 'A draft is created on the next run date, which then advances by one period.',
    '已剔除期初结转损益' => 'Opening profit or loss carryforward excluded',
    '这个区间没有已过账的损益分录，换一个期间再看看。' => 'No posted profit or loss entries exist in this period. Try another period.',
    '页面背景' => 'Page background',
    '卡片表面' => 'Card surface',
    '主要操作' => 'Primary actions',
    '辅助强调' => 'Secondary accent',
    '成功状态' => 'Success state',
    '工作台外观' => 'Workspace appearance',
    '让财务数据清晰，也让双眼舒适' => 'Clear financial data, comfortable viewing',
    '从明亮的报表工作台到低光环境的深色界面，选择适合你当前任务的配色。' => 'From a bright reporting workspace to a dark interface for low light, choose colors that suit your current task.',
    '当前主题' => 'Current theme',
    '深色模式' => 'Dark mode',
    '浅色模式' => 'Light mode',
    '已在此浏览器保存' => 'Saved in this browser',
    '选择配色方案' => 'Choose a color scheme',
    '所有主题只改变界面颜色，不影响功能布局、公司数据与报表内容。' => 'Themes only change interface colors. Layout, company data, and report content remain unchanged.',
    '%d 套主题' => '%d themes',
    '深色' => 'Dark',
    '浅色' => 'Light',
    '核心色彩样本' => 'Core color swatches',
    '核心色' => 'Core colors',
    '应用主题：%s' => 'Apply theme: %s',
    '应用主题' => 'Apply theme',
    '按工作场景选择' => 'Choose by work setting',
    '没有绝对最好的配色，适合当前光线与阅读时长更重要。' => 'There is no single best palette. Choose one that suits your lighting and reading time.',
    '明亮办公环境' => 'Bright offices',
    '科技蓝适合日常操作与对外展示；冰川青更清爽，雾蓝低对比更柔和。' => 'Tech Blue suits daily work and presentations; Glacier Teal feels fresh, while Mist Blue offers softer contrast.',
    '长时间阅读与复核' => 'Extended reading and review',
    '暖纸灰、赤陶暖棕和墨绿沉静能降低纯白底带来的视觉刺激。' => 'Warm Paper, Terracotta, and Deep Green reduce the glare of a plain white background.',
    '低光与夜间工作' => 'Low-light and night work',
    '石墨夜色偏中性，午夜靛蓝偏冷色；两者都提高了正文与状态色亮度。' => 'Graphite Night is neutral and Midnight Indigo is cooler; both brighten body text and status colors.',
    '主题选择会保存一年，仅影响当前浏览器；你可以随时切换，选择会立即生效。' => 'Your theme is saved for one year in this browser only. Switch at any time and the change applies immediately.',
    '留空自动生成，如 V-0001' => 'Leave blank to auto-generate, e.g. V-0001',
    '保存时自动递增编号' => 'The number increments automatically on save',
    '编辑供应商' => 'Edit vendor',

    // Inline help: command through period-close
    'AI 工作台：用自然语言查账、建单和记账，写操作必须经你确认。' => 'AI workspace: use natural language to query records, create documents, and post entries. Every write action requires your confirmation.',
    '先准备单据日期、往来单位、金额等资料，并在顶栏选择「会计」等合适岗位。' => 'Gather document dates, counterparties, and amounts, then choose a suitable role such as Accountant in the top bar.',
    '在底部输入框写清任务，例如「把 11 月银行流水对一下」，再按发送。' => 'Enter a clear request in the bottom box, such as Reconcile the November bank transactions, then send it.',
    '阅读结果卡片中的字段、明细与风险提示；科目不对时在卡片内重新选择。' => 'Review the fields, lines, and warnings in the result card. If an account is wrong, select another in the card.',
    '核对无误后点「确认记账」或「确认导入」；只想看建议可先点「改为只提案」。' => 'After checking, select Confirm posting or Confirm import. For advice only, select Change to proposal first.',
    '结果区会列出实际写入的单号或凭证号，可到对应详情页复查。' => 'The result lists the document or voucher numbers actually written, so you can verify them on their detail pages.',
    'AI 可能识别错误，金额、币种和日期必须人工核对；确认后的过账不能直接编辑。' => 'AI can misread data. Check amounts, currencies, and dates yourself; confirmed postings cannot be edited directly.',
    '经营概览：先看现金、盈亏和待办，再进入具体单据处理。' => 'Business overview: review cash, profit or loss, and tasks before opening individual documents.',
    '先选择趋势的「3M / 6M / 12M / 24M / 36M」范围，并确认「账簿截至」日期是否符合预期。' => 'Choose a 3M, 6M, 12M, 24M, or 36M trend range and confirm that the books-through date is as expected.',
    '需要录单时点「＋ 记收入」或「记支出」；有月结单则点「导入月结单」。' => 'Select + Record income or Record expense to enter a transaction, or Import statement if you have a bank statement.',
    '打开「逾期未收」或「待复核」分组，逐张处理列出的单据。' => 'Open Overdue receivables or Pending review and process each listed document.',
    '在「最近记账」打开凭证号，核对刚完成的业务是否已正确入账。' => 'Open a voucher number under Recent entries and verify that the transaction was recorded correctly.',
    '你能看清本期净利、现金、应收应付，并已打开今天要处理的单据。' => 'You can see net profit, cash, receivables, and payables, and have opened the documents to handle today.',
    '概览主要反映已过账数据，草稿不计入；账簿截至日期偏旧时，先补录和过账再判断经营状况。' => 'The overview mainly uses posted data and excludes drafts. If the books-through date is old, enter and post missing transactions before assessing performance.',
    '快速建单：在同一页录入销售发票、采购发票或费用。' => 'Quick entry: create sales invoices, bills, or expenses on one page.',
    '先准备好原始单据，再点「销售发票」「采购发票」或「费用」选择正确类型。' => 'Gather the source documents, then select Sales invoice, Bill, or Expense.',
    '填写客户或供应商、日期、到期日和币种；费用单还要选择「费用科目」。' => 'Enter the customer or vendor, date, due date, and currency. For an expense, also select an expense account.',
    '逐行填写摘要、数量、单价和科目，明细不够时点「＋ 加一行」。' => 'Enter the description, quantity, unit price, and account on each line. Select + Add line if you need more lines.',
    '先核对合计，再点「存为草稿」或「保存并记账」；已保存的发票和账单草稿可点「批量记账」。' => 'Check the total, then select Save draft or Save and post. Saved invoice and bill drafts can be posted with Batch post.',
    '列表出现新单号；选择记账后，详情状态为已记账并能查到对应凭证。' => 'The new document number appears in the list. After posting, its detail shows Posted and links to the voucher.',
    '费用在这里只保存草稿；批量记账只处理发票和账单草稿，过账（正式计入账簿）后不能再直接修改。' => 'Expenses are only saved as drafts here. Batch posting handles invoice and bill drafts only; posted entries cannot be edited directly.',
    '报价单：记录给客户的价格，接受后再转成销售发票。' => 'Quotes: record prices offered to customers and convert accepted quotes to sales invoices.',
    '先用「搜索报价单号 / 客户」查找是否已有报价；新建前准备客户、有效期和明细价格。' => 'Search by quote number or customer to avoid duplicates. Before creating one, prepare the customer, validity period, and line prices.',
    '点「新建报价单」，填写客户、报价日期、有效期至、明细和条款，再点「保存报价单」。' => 'Select New quote, enter the customer, quote date, valid-until date, lines, and terms, then select Save quote.',
    '发出后按实际进度点「标记已发出」，再选择「客户已接受」或「被拒绝」。' => 'After sending it, select Mark as sent, then Customer accepted or Rejected according to the actual outcome.',
    '客户接受后点「转发票」生成销售发票草稿，随后用「查看发票」继续复核和过账。' => 'Once accepted, select Convert to invoice to create a sales invoice draft, then View invoice to review and post it.',
    '报价状态与实际操作一致，转发票后能看到关联的销售发票草稿。' => 'The quote status matches reality, and conversion shows the linked sales invoice draft.',
    '报价单不进总账，只有转出的发票过账后才影响收入；已转发票的报价不要重复转换。' => 'Quotes do not enter the general ledger. Revenue changes only when the converted invoice is posted; do not convert the same quote again.',
    '贷记单：用红字单据处理退货、折让或发票、账单金额调整。' => 'Credit notes: use reversing documents for returns, allowances, or invoice and bill adjustments.',
    '先确认是客户还是供应商调整，并准备原发票或原账单编号、原因和金额。' => 'Confirm whether this is a customer or vendor adjustment, then prepare the source document number, reason, and amount.',
    '点「＋ 开贷记单」，选择类型、往来单位和原单，填写日期、币种、科目及原因。' => 'Select + New credit note, choose the type, counterparty, and source document, then enter the date, currency, account, and reason.',
    '核对明细后点「保存草稿」继续修改，或点「保存并过账」正式入账。' => 'Check the lines, then Save draft to continue editing or Save and post to record it formally.',
    '回到列表打开贷记单详情，核对状态、关联原单和生成的分录。' => 'Open the credit note from the list and verify its status, linked source document, and generated entry.',
    '贷记单显示预期状态；已过账记录能在日记账和相应报表中查到。' => 'The credit note shows the expected status, and posted records appear in the journal and relevant reports.',
    '过账后不能直接编辑；原单核销关系可能受贷记单影响，操作前应核对原单余额，不要仅凭红字金额判断。' => 'Posted credit notes cannot be edited directly. They may affect source-document settlement, so check the source balance first instead of relying only on the credit amount.',
    '循环交易：按固定频率生成重复发票、账单或费用。' => 'Recurring transactions: generate repeated invoices, bills, or expenses on a fixed schedule.',
    '先准备往来单位、固定金额、频率、首次执行日和结束日，确认是否允许自动记账。' => 'Prepare the counterparty, fixed amount, frequency, first run date, and end date, and decide whether auto-posting is appropriate.',
    '点「＋ 新建规则」，填写「规则名称」「单据类型」「频率」及金额等字段，再点「保存规则」。' => 'Select + New rule, enter the rule name, document type, frequency, amount, and other fields, then Save rule.',
    '在规则列表核对「下次执行」，需要立即建单时点「执行一次」。' => 'Check Next run in the rule list. Select Run once if you need to create a document immediately.',
    '金额或日期变化时点「编辑」修改规则；暂时不再生成则点「暂停」，恢复时点「启用」。' => 'Select Edit when amounts or dates change, Pause to stop generation temporarily, and Enable to resume.',
    '执行后出现新单号，规则的下次执行日自动向后推进一期。' => 'A run creates a new document number and advances the next run date by one period.',
    '「执行一次」会实际建单并推进日期，不要重复点击；费用规则只生成草稿，自动记账失败时仍需人工处理。' => 'Run once really creates a document and advances the date, so do not click it repeatedly. Expense rules create drafts only; failed auto-posting needs manual action.',
    '经常性发票：按月、季或年生成固定销售发票。' => 'Recurring invoices: generate fixed sales invoices monthly, quarterly, or yearly.',
    '先准备客户、收入金额、币种、频率和首次执行日，并核对收入科目是否合适。' => 'Prepare the customer, revenue amount, currency, frequency, and first run date, and confirm the revenue account.',
    '点「＋ 新建规则」，选择「销售发票」，填写规则名称、客户、金额、频率和摘要后保存。' => 'Select + New rule and Sales invoice, then enter the rule name, customer, amount, frequency, and description before saving.',
    '在列表确认「下次执行」和「生效」状态，需要提前出单时点「执行一次」。' => 'Confirm Next run and Active in the list. Select Run once to issue an invoice early.',
    '打开发票列表核对生成的草稿，补充附件并完成复核、过账；价格变化时先「编辑」规则。' => 'Open the invoice list, check the generated draft, add attachments, and complete review and posting. Edit the rule before prices change.',
    '生成的销售发票可在发票列表打开，规则显示新的下次执行日。' => 'The generated sales invoice opens from the invoice list, and the rule shows its new next run date.',
    '勾选「自动记账」也会实际过账，启用前必须确认金额和复核条件；暂停只停止以后建单，不删除历史发票。' => 'Auto-post really posts entries, so verify amounts and review requirements before enabling it. Pausing stops future documents but does not delete past invoices.',
    '经常性账单及费用：按规则生成固定采购账单或费用草稿。' => 'Recurring bills and expenses: generate fixed bills or expense drafts from rules.',
    '先准备供应商或费用类别、费用科目、金额、频率和首次执行日。' => 'Prepare the vendor or expense category, expense account, amount, frequency, and first run date.',
    '点「＋ 新建规则」，选择「账单」或「费用」，填写往来单位、金额、税额和费用科目后保存。' => 'Select + New rule and Bill or Expense, then enter the counterparty, amount, tax, and expense account before saving.',
    '核对「下次执行」后点「执行一次」，再到账单或费用列表补上当期原始凭证。' => 'Check Next run and select Run once, then add the current source documents in the bill or expense list.',
    '合同金额变化时点「编辑」；停止续订时点「暂停」，以后恢复再点「启用」。' => 'Select Edit when contract amounts change, Pause when renewal stops, and Enable to resume later.',
    '新账单或费用草稿出现在对应列表，规则的执行次数和下次执行日已更新。' => 'The new bill or expense draft appears in its list, and the rule updates its run count and next run date.',
    '费用规则不会自动过账；账单的自动记账也不能替代原始凭证核对，重复执行会重复建单。' => 'Expense rules never auto-post. Bill auto-posting does not replace source-document checks, and repeated runs create duplicate documents.',
    '核销工作台：集中查看未收、未付和已记账但未对账的项目。' => 'Settlement workspace: review unpaid receivables, unpaid bills, and posted entries awaiting reconciliation in one place.',
    '先看「应收未收」「应付未付」「逾期超 30 天」和「待对账分录」，确定要处理的一类。' => 'Review Outstanding receivables, Outstanding payables, Over 30 days overdue, and Entries to reconcile, then choose a category to process.',
    '需要收付款时点「登记收款」或「登记付款」，按未结金额完成核销。' => 'For incoming or outgoing funds, select Record receipt or Record payment and settle against the outstanding amounts.',
    '回到「待对账」逐张核对凭证号、日期、摘要和金额，只勾选确实无需银行流水匹配或已经核实的项目。' => 'Return to To reconcile and check each voucher number, date, description, and amount. Select only items that need no bank match or have been verified.',
    '点「确认对账」，在确认提示中再次检查所选凭证后提交。' => 'Select Confirm reconciliation, check the selected vouchers again in the prompt, and submit.',
    '已收付单据的未结金额减少，已确认的待对账分录从清单消失并纳入报表。' => 'Outstanding balances fall after receipts or payments, and confirmed entries leave the reconciliation list and enter the reports.',
    '确认对账不会修改分录金额，但会改变报表纳入口径；不要为清空列表而勾选未核实的凭证。' => 'Confirming reconciliation does not change entry amounts but does change report inclusion. Never select unverified vouchers just to clear the list.',
    '月结：按六步流水线核对当月账务，最后锁定期间。' => 'Period close: check the month through six steps, then lock the period.',
    '先在右上角选择月份并点「切换期间」，确认「本期」和当前锁定状态。' => 'Choose a month at the top right and select Switch period. Confirm the current period and lock status.',
    '点「执行可自动的步骤」，查看银行对账、汇率等步骤的结果是完成还是需处理。' => 'Select Run automatic steps and see whether bank reconciliation, exchange rates, and other steps are complete or need action.',
    '通过「相关页面」进入对账、核销、期末重估等页面处理，再回来对相应步骤点「执行」。' => 'Use Related pages to handle reconciliation, settlement, and revaluation, then return and select Run for the relevant step.',
    '确认应收应付、计提和报表均已复核后，在最后一步点「锁账并完成」。' => 'After reviewing receivables, payables, accruals, and reports, select Lock and complete in the final step.',
    '完成进度显示 6/6，期间状态为已锁定，财务报表可按期复核。' => 'Progress shows 6/6 and the period is Locked, ready for financial statement review.',
    '月结中的重估步骤只记录进度，不代替「期末重估」生成凭证；已关闭期间不可重开，锁定后写入会受阻止。' => 'The close checklist only records revaluation progress; it does not create vouchers. Closed periods cannot be reopened, and locked periods block writes.',

    // Inline help: tax through ai-close
    '利得税：查看课税年度利润、两级制资格和预计应缴税额。' => 'Profits tax: review annual profits, two-tier rates eligibility, and estimated tax payable.',
    '先通过期间选择器或「切换课税年度」确定年度，核对显示的基期起止日期。' => 'Use the period selector or Switch tax year, then verify the displayed basis-period start and end dates.',
    '查看「计算过程」中的收入、销售成本、经营费用和除税前溢利，与损益表交叉核对。' => 'Review revenue, cost of sales, operating expenses, and profit before tax in Calculation, and cross-check them against the income statement.',
    '管理员按税务事实选择「已提名两级制」「未提名」或「暂不确定」，填写「依据」后点「保存资格」。' => 'An administrator selects Nominated for two-tier rates, Not nominated, or Undetermined based on the tax facts, enters the basis, and selects Save eligibility.',
    '需要调整明细时打开「利得税计算表」；需要留档时使用页面导出菜单下载 PDF。' => 'Open Profits tax computation to adjust details, or use the export menu to download a PDF for your records.',
    '资格状态、适用税率和应缴利得税均已显示，且计算年度与基期一致。' => 'Eligibility, applicable rates, and profits tax payable are shown for the correct year and basis period.',
    '资格未确定时系统不会估税；修改资格会改变税额并留下审计记录，最终申报应由合资格专业人士复核。' => 'Tax is not estimated while eligibility is undetermined. Changes affect tax and are audited; a qualified professional should review the final filing.',
    '报表中心：统一选择期间、检查勾稽关系并打开或导出报表。' => 'Report center: choose a period, check accounting tie-outs, and open or export reports.',
    '先在期间栏填写起止日期并应用，确认快照期间正是要查看的区间。' => 'Enter and apply the start and end dates, then confirm the snapshot covers the intended period.',
    '检查「勾稽校验」中的资产负债表和试算表是否都显示平衡，再阅读收入、毛利和净利。' => 'Confirm that both the balance sheet and trial balance show Balanced under Tie-out checks, then review revenue, gross profit, and net profit.',
    '在「全部报表」点具体报表标题，或在「导出」区选择所需语言下载单张 PDF。' => 'Select a report title under All reports, or choose a language under Export to download one PDF.',
    '需要整包时填写年度 PDF 包的日期、语言和编号年份，勾选内容后点「生成报表包（ZIP）」。' => 'For a full package, enter the annual PDF dates, language, and numbering year, select the contents, and choose Generate report package (ZIP).',
    '报表数字属于所选期间且两项勾稽均平衡；ZIP 任务完成后出现「下载 ZIP」。' => 'Report figures cover the selected period and both tie-outs balance. Download ZIP appears when the package is ready.',
    '不平衡时不要对外出具报表；包含大量销售单和采购单的 ZIP 生成较慢，后台任务完成前不要重复提交。' => 'Do not issue unbalanced reports. Large packages with many sales and purchase documents take longer; do not resubmit while the background task runs.',
    '智能体管理：查看岗位编制、运行记录、学习规则和可用工具。' => 'Agent management: review roles, run history, learned rules, and available tools.',
    '先在「编制」页确认会计、出纳、复核等岗位的职责，再确定要检查的智能体。' => 'On Roles, confirm the responsibilities of Accountant, Cashier, Reviewer, and other agents, then choose one to inspect.',
    '打开「运行记录」，按时间查看执行结果和异常，必要时回到原业务单据核对。' => 'Open Run history to review outcomes and errors by time, returning to the source documents when needed.',
    '在「学习台账」检查识别建议，确认样本无误后点「立刻固化识别规则」或「立刻固化一次」。' => 'Check recognition suggestions in Learning log. After validating the samples, select Save recognition rules now or Save once now.',
    '到「工具」核对智能体可调用的功能；不再使用的学习规则可点「停用」，需要时再「启用」。' => 'Check available functions under Tools. Disable learned rules that are no longer useful and enable them again when needed.',
    '运行记录能解释实际动作，已固化或停用的规则在学习台账中显示最新状态。' => 'Run history explains the actual actions, and Learning log shows the latest saved or disabled rule status.',
    '固化规则会影响后续识别建议，停用不会撤回已生成单据；不要仅凭一次样本就固化不确定的规则。' => 'Saved rules affect future suggestions. Disabling a rule does not undo generated documents; do not save an uncertain rule from one sample alone.',
    'AI 工作台：提问查账，或从发票文件、文本中提取建单字段。' => 'AI workspace: ask accounting questions or extract document fields from invoice files and text.',
    '先准备要问的期间、客户或单号；识别单据时准备清晰文件或完整发票文本。' => 'Prepare the period, customer, or document number for your question. For extraction, provide a clear file or complete invoice text.',
    '查账时在问题框输入具体条件并点「提问」，核对回答引用的数字和期间。' => 'Enter specific conditions in the question box and select Ask. Verify the figures and periods cited in the answer.',
    '识别单据时上传文件或粘贴文本，点「识别并提取字段」，逐项检查往来单位、日期、币种和金额。' => 'Upload a file or paste text, select Recognize and extract fields, then check the counterparty, date, currency, and amounts.',
    '确认识别结果后点「作为采购发票（支出）」或「作为销售发票（收入）」，继续在建单流程中核对。' => 'After checking the extraction, select Use as bill (expense) or Use as sales invoice (income), then continue verification in the entry workflow.',
    '问题得到对应期间的结果，或识别字段被带入正确的销售、采购建单流程。' => 'The answer covers the requested period, or the extracted fields flow into the correct sales or purchase workflow.',
    'OCR 和 AI 可能误读金额、税项及币种；生成草稿不等于过账，正式入账前仍须人工复核。' => 'OCR and AI can misread amounts, tax, and currencies. A generated draft is not posted; review it manually before formal entry.',
    '销售发票列表：查找、新建和跟踪客户发票的草稿及过账状态。' => 'Sales invoice list: find and create customer invoices and track draft and posted statuses.',
    '先选择「全部发票」「草稿」或「已记账」，再输入「搜索发票号 / 客户」并点「搜索」。' => 'Choose All invoices, Drafts, or Posted, enter an invoice number or customer, and select Search.',
    '没有目标单据时点「+ 新建发票」；已有草稿则点「编辑草稿」补齐内容。' => 'Select + New invoice if no document exists, or Edit draft to complete an existing draft.',
    '点发票号进入详情，检查客户、到期日、明细、附件和复核状态。' => 'Open the invoice number and check the customer, due date, lines, attachments, and review status.',
    '草稿确认无误后按详情页流程提交复核并过账；不再需要的草稿才使用删除。' => 'After checking a draft, submit it for review and post it through the detail workflow. Delete only drafts you no longer need.',
    '搜索条件和状态筛选正确，目标发票能打开，过账后状态显示已记账。' => 'The filters return the intended invoice, its detail opens, and posting changes its status to Posted.',
    '删除草稿不可恢复；已过账发票不能直接改金额，应通过冲销或贷记单更正。' => 'Draft deletion is irreversible. Posted invoice amounts cannot be edited directly; correct them by reversal or credit note.',
    '新建销售发票：录入客户、明细和汇率，保存草稿或直接过账。' => 'New sales invoice: enter the customer, lines, and exchange rate, then save a draft or post directly.',
    '先准备客户资料、发票日期、到期日、币种和原始凭证，外币还要准备真实汇率。' => 'Prepare the customer details, invoice date, due date, currency, and source documents, plus the actual exchange rate for foreign currency.',
    '选择客户并填写日期、到期日和币种，逐行输入摘要、数量、单价及收入科目。' => 'Select the customer and enter the date, due date, and currency. On each line, enter the description, quantity, unit price, and revenue account.',
    '明细不足时点「＋ 添加一行」，上传附件后核对合计、税额和港币折算金额。' => 'Select + Add line for more lines, upload attachments, and check the total, tax, and HKD conversion.',
    '还需修改时点「保存草稿」；编辑已有草稿点「保存修改」，确认无误才点「保存并过账」。' => 'Select Save draft to keep editing or Save changes for an existing draft. Use Save and post only after verification.',
    '系统显示新发票号和保存状态；过账后可在详情看到对应记账凭证。' => 'The system shows the new invoice number and save status; posting adds the accounting voucher to its detail.',
    '金额由明细计算，不要用手工总数替代；外币缺少真实汇率会被拦截，过账后不可直接编辑。' => 'Amounts are calculated from the lines, so do not replace them with a manual total. Missing actual FX rates block foreign-currency invoices; posted invoices cannot be edited directly.',
    '销售发票详情：核对一张发票的明细、附件、复核和记账结果。' => 'Sales invoice detail: verify one invoice, its attachments, review, and posting result.',
    '先核对发票号、客户、日期、币种和状态，确认打开的是要处理的单据。' => 'Check the invoice number, customer, date, currency, and status to confirm you opened the intended document.',
    '逐行检查明细和合计，并用「上传附件」补齐合同、送货单等原始凭证。' => 'Check every line and the total, then use Upload attachment to add contracts, delivery notes, and other source documents.',
    '草稿需要修改时点「编辑草稿」；资料齐全后点「提交复核」，由复核人选择「批准」或「退回」。' => 'Select Edit draft to make changes. When ready, Submit for review so a reviewer can Approve or Return it.',
    '批准且校验通过后执行过账；需要寄送时点「发送邮件」，先确认收件人和 PDF。' => 'Post after approval and successful validation. To send it, select Send email and confirm the recipients and PDF first.',
    '详情显示最新复核与过账状态，已过账时能打开对应凭证，附件数量正确。' => 'The detail shows the latest review and posting status, opens the voucher after posting, and lists the correct attachments.',
    '退回时要写清原因；过账后不能编辑或删除，只能按更正流程冲销或开贷记单。' => 'Give a clear reason when returning a document. Posted invoices cannot be edited or deleted; reverse them or issue a credit note instead.',
    '通用单据详情：查看报价单、贷记单、费用或分录及其附件。' => 'Document detail: view a quote, credit note, expense, or journal entry with its attachments.',
    '先核对页面标题、单据编号和「状态」，确认单据类型与来源列表无误。' => 'Check the page title, document number, and Status to confirm the type and source list.',
    '查看「单据信息」及「明细」或「分录行」，逐项核对日期、科目、借贷和金额。' => 'Review Document details and Lines or Entry lines, checking dates, accounts, debits, credits, and amounts.',
    '在「附件」区点「查看」核对原件；缺件时选择文件并点「上传附件」。' => 'Under Attachments, select View to inspect source files. Choose a file and Upload attachment if anything is missing.',
    '草稿需要修改时点「编辑草稿」；报价单或贷记单可用「发送邮件」「导出 PDF」，完成后点「返回列表」。' => 'Select Edit draft for changes. Quotes and credit notes support Send email and Export PDF; select Back to list when finished.',
    '页面字段、明细与原始单据一致，新上传附件能在列表中打开。' => 'The fields and lines match the source document, and newly uploaded attachments open from the list.',
    '只有草稿可编辑；删除草稿或附件不可恢复，已过账分录应冲销而不是删除。' => 'Only drafts are editable. Draft and attachment deletion is irreversible; reverse posted entries instead of deleting them.',
    '往来单位详情：集中查看客户或供应商资料、欠款和关联单据。' => 'Counterparty detail: review customer or vendor details, outstanding balances, and linked documents.',
    '先核对单位名称、类型和编号，确认当前是要查询的客户或供应商。' => 'Check the name, type, and code to confirm this is the intended customer or vendor.',
    '查看基本资料与联系人，检查默认币种、付款条件和联系方式是否完整。' => 'Review the profile and contacts, checking the default currency, payment terms, and contact details.',
    '核对应收或应付未结金额，再打开关联发票或账单逐张追查余额来源。' => 'Check the outstanding receivable or payable, then open linked invoices or bills to trace the balance.',
    '资料需要变更时点「编辑资料」；核对完成后点「返回列表」。' => 'Select Edit details to update information, or Back to list after checking.',
    '联系人、欠款和关联单据均与原始资料一致，编辑后详情显示新内容。' => 'Contacts, balances, and linked documents match the source records, and edits appear in the detail.',
    '未结金额来自关联业务单据，不能在档案页直接改数；修改名称或币种前应确认不会影响后续开单。' => 'Outstanding amounts come from linked documents and cannot be edited here. Confirm that name or currency changes will not disrupt future documents.',
    '月结概览：只读查看六步收尾进度和费用构成，并返回 AI 对话继续处理。' => 'Close overview: read the six-step progress and expense breakdown, then return to the AI conversation to continue.',
    '先确认页面显示的结账期间，准备本期银行、应收应付和费用核对资料。' => 'Confirm the closing period shown, then prepare the bank, receivable, payable, and expense records for that period.',
    '按顺序阅读六个步骤的完成状态，记下仍未完成或需人工处理的项目。' => 'Read all six step statuses in order and note anything incomplete or requiring manual work.',
    '查看费用构成，核对主要费用科目和金额是否与本期凭证相符。' => 'Review the expense breakdown and check major expense accounts and amounts against current-period vouchers.',
    '点「回到对话」，让 AI 继续执行月结动作，并在每个写入确认卡片中人工核对。' => 'Select Back to conversation to continue close actions with AI, manually checking every write-confirmation card.',
    '你能明确本期已完成和未完成步骤，并能从对话中的结果单号回查处理结果。' => 'You can identify completed and outstanding steps and trace the resulting document numbers from the conversation.',
    '本页只读，不会因查看而完成月结；实际锁账、重估等动作仍须在 AI 对话中确认，锁账后不能直接改账。' => 'This page is read-only. Locking, revaluation, and other actions still require confirmation in the AI conversation; locked books cannot be edited directly.',

    // Inline help: settings-llm through bill-new
    '大模型设置：配置 AI 服务地址、模型、温度和密钥，并测试连通性。' => 'LLM settings: configure the AI endpoint, model, temperature, and API key, then test connectivity.',
    '先向服务商确认「服务地址（Base URL）」、可用「模型」和 API Key，不要猜填地址。' => 'Confirm the Base URL, available model, and API key with your provider; do not guess the endpoint.',
    '填写服务地址与模型，按需要调整「温度」；保留旧密钥时把「API Key」留空。' => 'Enter the endpoint and model and adjust Temperature if needed. Leave API Key blank to keep the existing key.',
    '点「保存配置」，看到保存成功后再进行连接测试。' => 'Select Save configuration and wait for the success message before testing the connection.',
    '点单独的「测试连接」，根据返回结果检查地址、模型、密钥或网络。' => 'Select Test connection separately, then use the result to check the endpoint, model, key, or network.',
    '配置保存成功且测试连接通过，AI 页面即可按新配置发起请求。' => 'The configuration is saved and the connection test passes, so AI pages can use the new settings.',
    '环境变量可能覆盖页面填写的地址或密钥；密钥属于敏感信息，不要截图外发，温度越高回答越发散。' => 'Environment variables may override the endpoint or key. Keep keys out of screenshots and messages; higher temperatures produce more varied answers.',
    '外观与配色：切换当前浏览器的界面主题，不改变账务数据。' => 'Appearance and colors: change the interface theme in this browser without changing accounting data.',
    '先查看各主题卡片的配色预览，选择适合长时间阅读和打印前核对的一款。' => 'Review the theme previews and choose one suitable for extended reading and pre-print checks.',
    '在目标卡片点「应用主题」，等待页面颜色立即更新。' => 'Select Apply theme on the preferred card and watch the page colors update immediately.',
    '打开常用菜单、表单和报表，检查文字、按钮与表格是否清晰。' => 'Open familiar menus, forms, and reports to check that text, buttons, and tables remain clear.',
    '不合适时回到本页，在另一张卡片点「应用主题」即可随时更换。' => 'If it does not suit you, return here and Apply theme on another card at any time.',
    '目标卡片显示「正在使用」，全站界面颜色与所选主题一致。' => 'The selected card shows In use, and the interface colors match that theme throughout the site.',
    '主题只保存在当前浏览器约一年，不会同步到其他设备，也不会修改公司资料、单据或报表金额。' => 'The theme stays in this browser for about one year. It does not sync to other devices or change company data, documents, or report amounts.',
    '销售订单：登记客户订货、交付和转发票进度，本身不进总账。' => 'Sales orders: track customer orders, delivery, and invoicing without posting directly to the general ledger.',
    '先在「搜索订单号 / 往来单位」查找现有订单；新建前准备客户、合同参考、交付日期和价格明细。' => 'Search by order number or counterparty for an existing order. Before creating one, prepare the customer, contract reference, delivery date, and prices.',
    '点「＋ 新建销售订单」，填写客户、合同或参考号、日期、状态及明细，再点「建销售订单」。' => 'Select + New sales order, enter the customer, contract or reference, dates, status, and lines, then Create sales order.',
    '在列表点订单号查看详情；草稿资料需要调整时点「编辑订单」并「保存修改」。' => 'Open the order number for details. To adjust a draft, select Edit order and Save changes.',
    '交付后登记交付，再点「转成销售发票草稿」或列表的「转发票」，到发票页完成复核和过账。' => 'After delivery, record it, then Convert to sales invoice draft or use Convert to invoice in the list. Review and post from the invoice page.',
    '订单状态、已交付数量和关联发票一致，转出的发票草稿可以打开。' => 'The order status, delivered quantities, and linked invoice agree, and the generated invoice draft opens correctly.',
    '订单和交付不会直接确认收入；「取消订单」或「标记已关闭」会影响后续转换，操作前先核对未交付数量。' => 'Orders and deliveries do not recognize revenue. Cancel order and Mark closed affect later conversion, so check undelivered quantities first.',
    '采购订单：登记向供应商订货、收货和转账单进度，本身不进总账。' => 'Purchase orders: track vendor orders, receipts, and billing without posting directly to the general ledger.',
    '先在「搜索订单号 / 往来单位」查找是否重复下单，并准备供应商、参考号、收货日期和价格。' => 'Search by order number or counterparty to avoid duplicates, and prepare the vendor, reference, receipt date, and prices.',
    '点「＋ 新建采购订单」，填写供应商、日期、状态和明细，再点「建采购订单」。' => 'Select + New purchase order, enter the vendor, dates, status, and lines, then Create purchase order.',
    '打开订单详情核对合同与收货情况，资料变化时点「编辑订单」修改。' => 'Open the order detail to check the contract and receipts. Select Edit order when information changes.',
    '收货后登记收货，再点「转成采购发票草稿」或列表的「转账单」，继续上传原件、复核和过账。' => 'After receiving goods, record the receipt, then Convert to bill draft or use Convert to bill in the list. Upload source documents, review, and post.',
    '订单的收货数量与供应商实际交付一致，关联账单草稿已生成。' => 'Received quantities match the vendor delivery, and the linked bill draft has been created.',
    '采购订单和收货不直接计入成本费用；取消或关闭订单前确认没有待收货、待转账单的数量。' => 'Purchase orders and receipts do not directly record costs or expenses. Before cancelling or closing, confirm nothing remains to receive or bill.',
    '订单详情：处理合同、交付或收货、关闭取消及转发票、账单。' => 'Order detail: manage contracts, delivery or receipt, closure or cancellation, and invoice or bill conversion.',
    '先核对订单号、客户或供应商、币种、状态和明细，确认合同参考号与原始订单一致。' => 'Check the order number, customer or vendor, currency, status, and lines, and confirm the contract reference matches the source order.',
    '需要补合同用「上传合同」，草稿资料有误点「编辑订单」，对外留档可点「打印 / PDF」或「发送邮件」。' => 'Use Upload contract for missing contracts and Edit order for draft corrections. Use Print / PDF or Send email for external records.',
    '按实际进度点「登记交付」或「登记收货」，填写本次数量并核对累计数量。' => 'Select Record delivery or Record receipt as appropriate, enter the current quantity, and check the cumulative quantity.',
    '需要入账时点「转成销售发票草稿」或「转成采购发票草稿」，再进入单据详情复核和过账。' => 'To record the transaction, select Convert to sales invoice draft or Convert to bill draft, then open the document to review and post.',
    '订单显示最新交付或收货数量，关联草稿已生成且金额、数量与订单一致。' => 'The order shows current delivery or receipt quantities, and the linked draft matches its amounts and quantities.',
    '订单本身不生成会计凭证；「标记已关闭」会停止后续履约，「取消订单」应谨慎使用，已转出的单据不会随订单自动撤回。' => 'Orders create no accounting entries. Mark closed stops further fulfilment; use Cancel order carefully because converted documents are not automatically withdrawn.',
    '客户档案：维护开票对象、默认币种、付款条件和联系方式。' => 'Customer records: maintain billing parties, default currencies, payment terms, and contact details.',
    '先搜索客户名称或编号，避免重复建档，并准备合同上的法定名称和账单资料。' => 'Search by customer name or code to avoid duplicates, and prepare the legal name and billing details from the contract.',
    '点「＋ 新建客户」，填写客户类型、编号、名称、默认币种和付款条件。' => 'Select + New customer and enter the customer type, code, name, default currency, and payment terms.',
    '按实际填写关联方、联系人、电话、邮箱和地址，核对后点「保存」。' => 'Enter related-party status, contacts, phone, email, and address as applicable, check them, and Save.',
    '在列表打开客户详情，检查未结发票和联系方式；资料变化时进入「编辑资料」更新。' => 'Open the customer detail to check outstanding invoices and contacts. Use Edit details when information changes.',
    '客户出现在列表且详情资料完整，新建发票时能选到该客户和默认条件。' => 'The customer appears in the list with complete details and is selectable with the correct defaults on new invoices.',
    '客户名称应与合同及发票一致；关联方标识会影响披露，历史单据不会因修改或停用档案而消失。' => 'Customer names should match contracts and invoices. Related-party status affects disclosures; editing or disabling a record does not remove historical documents.',
    '采购账单列表：查找供应商账单，跟踪草稿、过账和后续付款。' => 'Bill list: find vendor bills and track drafts, posting, and subsequent payments.',
    '先输入「搜索单号 / 供应商 / 对方发票号」并点「搜索」，避免重复录入同一张供应商发票。' => 'Search by document number, vendor, or vendor invoice number to avoid entering the same vendor invoice twice.',
    '没有记录时点「新建账单」；已有草稿点「编辑草稿」补明细和附件。' => 'Select New bill if no record exists, or Edit draft to add lines and attachments.',
    '点账单号进入详情，核对供应商、对方发票号、到期日、税额和费用科目。' => 'Open the bill number and check the vendor, vendor invoice number, due date, tax, and expense accounts.',
    '草稿完成复核后点「过账」；需要付款时转到「付款核销」选择该账单。' => 'After reviewing a draft, select Post. To pay it, go to Payment allocation and select the bill.',
    '目标账单状态正确，过账后能查看凭证，付款后未付金额相应减少。' => 'The bill shows the correct status and voucher after posting, and its outstanding balance falls after payment.',
    '删除草稿不可恢复；过账后不能直接修改，重复供应商发票必须先查证再处理。' => 'Draft deletion is irreversible. Posted bills cannot be edited directly; investigate suspected duplicate vendor invoices before processing them.',
    '采购账单详情：核对供应商原件、明细、复核、过账和付款基础。' => 'Bill detail: verify the vendor source document, lines, review, posting, and payment basis.',
    '先核对账单号、供应商、对方发票号、日期、币种和状态，防止打开重复单据。' => 'Check the bill number, vendor, vendor invoice number, date, currency, and status to avoid duplicate documents.',
    '逐行检查费用或成本科目、数量、单价和税额，并用「上传附件」补供应商原件。' => 'Check each expense or cost account, quantity, unit price, and tax amount, then Upload attachment for the vendor source document.',
    '草稿有误点「编辑草稿」；资料齐全后点「提交复核」，由复核人选择「批准」或「退回」。' => 'Select Edit draft to correct errors. When ready, Submit for review so a reviewer can Approve or Return it.',
    '批准且校验通过后执行过账，再到「付款核销」按未结金额登记付款。' => 'Post after approval and successful validation, then go to Payment allocation and record a payment against the outstanding amount.',
    '详情显示批准及已记账状态，能查到对应凭证，附件与供应商原件一致。' => 'The detail shows approval and Posted status, links to the voucher, and contains attachments matching the vendor source document.',
    '税额和科目会影响损益及税务计算；过账后不可直接编辑，付款不在这个详情页完成。' => 'Tax and accounts affect profit or loss and tax calculations. Posted bills cannot be edited directly; payments are made outside this detail page.',
    '费用列表：查找没有供应商账单的小额支出及其凭证和状态。' => 'Expense list: find small expenses without vendor bills and inspect their vouchers and statuses.',
    '先在「搜索费用号 / 用途 / 项目 / 备注」输入条件并点「搜索」，需要重看全部时点「清除」。' => 'Search by expense number, purpose, project, or note. Select Clear to return to the full list.',
    '没有记录时点「+ 新建费用」，按支出用途和真实科目录入。' => 'If no record exists, select + New expense and enter the purpose and correct account.',
    '点费用号打开详情，核对日期、项目、费用科目、原币、折 HKD 和附件。' => 'Open the expense number and check the date, project, expense account, original currency, HKD equivalent, and attachments.',
    '草稿需要更正时点「编辑草稿」；确认不再需要的草稿才使用删除。' => 'Select Edit draft to make corrections. Delete only drafts you are certain are no longer needed.',
    '列表状态与详情一致，费用金额能在对应科目和损益报表中追查。' => 'The list and detail statuses agree, and expense amounts trace to the relevant accounts and income statement.',
    '删除草稿不可恢复；小额支出也应保留收据，已过账费用不能直接改科目或金额。' => 'Draft deletion is irreversible. Keep receipts even for small expenses; posted expense accounts and amounts cannot be edited directly.',
    '新建采购账单：按供应商原件录入明细、税额和真实汇率。' => 'New bill: enter lines, tax, and the actual exchange rate from the vendor source document.',
    '先准备供应商发票原件、对方发票号、账单日期、到期日、币种和费用科目。' => 'Prepare the vendor invoice, vendor invoice number, bill date, due date, currency, and expense accounts.',
    '选择供应商并填写日期、到期日和币种，逐行输入摘要、数量、单价及费用或成本科目。' => 'Select the vendor and enter the date, due date, and currency. Enter each description, quantity, unit price, and expense or cost account.',
    '明细不足时点「＋ 增加一行」，上传原件并核对合计、税额及外币折算。' => 'Select + Add line for more lines, upload the source document, and check the total, tax, and foreign-currency conversion.',
    '还需核对时点「保存草稿」；编辑草稿点「保存修改」，确认无误才点「保存并过账」。' => 'Select Save draft for further checks or Save changes for an existing draft. Use Save and post only after verification.',
    '系统显示账单号和状态；过账后详情有对应凭证，未付金额进入应付。' => 'The system shows the bill number and status. Posting links a voucher and records the unpaid amount in payables.',
    '外币必须有真实汇率，税额不要凭估计填写；过账后不能直接修改，重复原件不要重复入账。' => 'Foreign currency requires an actual exchange rate, and tax must not be estimated. Posted bills cannot be edited directly; never enter duplicate source documents twice.',

    // Inline help: expense-new through opening-balances
    '新建费用：录入打车、办公、招待等支出，并保存收据附件。' => 'New expense: enter transport, office, entertainment, and other expenses with receipt attachments.',
    '先准备收据，明确「支出用途」、所属「项目」和应计入的「费用科目」。' => 'Prepare the receipt and identify the expense purpose, project, and correct expense account.',
    '填写费用编号、日期、币种、金额（不含税）和税额，必要时填写复核人与备注。' => 'Enter the expense number, date, currency, amount excluding tax, and tax. Add a reviewer and notes when needed.',
    '把小票或发票扫描件拖到附件区，核对「合计」等于不含税金额加税额。' => 'Drag the receipt or invoice scan into Attachments and confirm Total equals the net amount plus tax.',
    '新单可点「保存草稿」或「保存并过账」；编辑已有草稿时点「保存修改」。' => 'For a new expense, select Save draft or Save and post. For an existing draft, select Save changes.',
    '保存后出现费用号和校验结果，附件已挂上；过账后可在日记账查到分录。' => 'Saving shows the expense number and validation result with attachments linked; posting makes the entry available in the journal.',
    '费用科目决定损益分类，不要全部使用默认科目；过账后不可直接编辑，无票据原因应写进备注。' => 'The expense account determines its profit-or-loss category, so do not use the default for everything. Posted expenses cannot be edited directly; explain missing receipts in Notes.',
    '供应商档案：维护付款对象、默认币种、付款条件和联系资料。' => 'Vendor records: maintain payment parties, default currencies, payment terms, and contact details.',
    '先搜索供应商名称或编号，避免重复建档，并准备供应商账单和收款资料。' => 'Search by vendor name or code to avoid duplicates, and prepare the vendor billing and payment details.',
    '点「＋ 新建供应商」，填写供应商类型、编号、名称、默认币种和付款条件。' => 'Select + New vendor and enter the vendor type, code, name, default currency, and payment terms.',
    '按实际填写关联方、联系人、电话、邮箱和地址，核对后点「保存」。' => 'Enter related-party status, contacts, phone, email, and address as applicable, check them, and Save.',
    '打开供应商详情检查关联账单和未付金额，资料变化时进入「编辑资料」更新。' => 'Open the vendor detail to check linked bills and outstanding amounts. Use Edit details when information changes.',
    '供应商出现在列表，新建账单时能选到该供应商及默认付款条件。' => 'The vendor appears in the list and is selectable with the correct default payment terms on new bills.',
    '名称应与供应商发票和付款记录一致；关联方标识及默认币种不要猜填，历史账单不受档案停用影响。' => 'Names should match vendor invoices and payment records. Do not guess related-party status or default currency; disabling a record does not affect historical bills.',
    '收款核销：登记客户来款，并把金额分配到一张或多张未结发票。' => 'Receipt allocation: record customer receipts and allocate them to one or more outstanding invoices.',
    '先准备银行到账日期、金额、币种和客户，并选择实际收款的银行账户。' => 'Prepare the bank credit date, amount, currency, and customer, then select the bank account that received the funds.',
    '在「搜索待核销单据号 / 往来单位」查找发票，核对每张的未结金额。' => 'Search open documents by number or counterparty, then check each invoice outstanding amount.',
    '在「本方核销额」填写本次分配金额，确保核销合计不超过收款金额。' => 'Enter each allocation in Amount to allocate, ensuring the total does not exceed the receipt.',
    '点「登记并核销」；编辑已有草稿则点「保存草稿」，随后打开记录核对核销明细。' => 'Select Record and allocate, or Save draft when editing an existing draft, then open the record to verify its allocations.',
    '系统显示收款编号和核销张数，相关发票未收金额减少，银行与总账产生对应记录。' => 'The system shows the receipt number and allocated document count. Invoice balances fall, with matching bank and general-ledger records.',
    '跨币种核销（以来款抵销发票欠款）会产生汇兑差额；登记后不要重复录同一笔到账，错误记录应按更正流程处理。' => 'Cross-currency allocation can create exchange differences. Do not enter the same bank credit twice; correct errors through the correction workflow.',
    '付款核销：登记供应商付款，并把金额分配到一张或多张未结账单。' => 'Payment allocation: record vendor payments and allocate them to one or more outstanding bills.',
    '先准备银行扣款日期、金额、币种和供应商，并选择实际付款的银行账户。' => 'Prepare the bank debit date, amount, currency, and vendor, then select the bank account used for payment.',
    '在「搜索待核销单据号 / 往来单位」查找账单，核对未结金额和到期日。' => 'Search open documents by number or counterparty, then check each bill outstanding amount and due date.',
    '在「本方核销额」填写本次分配金额，部分付款也可以，但合计不得超过付款金额。' => 'Enter each allocation in Amount to allocate. Partial payments are allowed, but the total cannot exceed the payment.',
    '点「登记并核销」；编辑已有草稿则点「保存草稿」，再打开详情核对账单余额。' => 'Select Record and allocate, or Save draft when editing an existing draft, then open the detail to verify bill balances.',
    '系统显示付款编号和核销结果，相关账单未付金额减少，汇兑差额单独列示。' => 'The system shows the payment number and allocation result. Bill balances fall, and exchange differences are listed separately.',
    '跨币种付款会影响汇兑损益；付错供应商或银行账户不要简单重复补录，应先按更正流程处理原记录。' => 'Cross-currency payments affect exchange gains or losses. For the wrong vendor or bank account, correct the original record instead of entering another payment.',
    '收付款详情：查看银行金额、核销单据、汇兑差额和生成的分录。' => 'Receipt or payment detail: review the bank amount, allocations, exchange differences, and generated entry.',
    '先核对收付款编号、方向、日期、银行账户、币种和状态。' => 'Check the transaction number, direction, date, bank account, currency, and status.',
    '查看金额与往来单位，确认它对应银行流水中的一笔真实收付。' => 'Review the amount and counterparty, and confirm it matches a real bank receipt or payment.',
    '在「核销明细」逐张检查本次核销、累计已核销、跨币种和汇兑差额。' => 'Under Allocation details, check each current and cumulative allocation, cross-currency flag, and exchange difference.',
    '打开关联会计分录；草稿需要更正时点「编辑草稿」，需要删除时先确认没有误核销。' => 'Open the linked accounting entry. Select Edit draft for corrections; before deleting a draft, confirm its allocations are not needed.',
    '核销合计与收付款金额勾稽一致，关联发票或账单的未结余额正确。' => 'Allocated totals reconcile to the receipt or payment, and linked invoice or bill balances are correct.',
    '汇兑差额是折算产生的损益，不是银行手续费；删除或修改草稿会改变核销关系，过账记录不能直接改。' => 'Exchange differences arise from conversion and are not bank fees. Draft edits or deletion change allocations; posted records cannot be edited directly.',
    '银行账户：维护账套中的银行及信用卡账户，并查看原币和港币余额。' => 'Bank accounts: maintain bank and credit-card accounts and view original-currency and HKD balances.',
    '先准备账户名称、币种、开户行、账号和期初余额；新币种先在「汇率维护」录入汇率。' => 'Prepare the account name, currency, bank, account number, and opening balance. For a new currency, enter its rate under Exchange rates first.',
    '点「+ 新增银行账户」，填写账户资料；信用卡要勾选「信用卡账户」。' => 'Select + New bank account and enter its details. Select Credit card account when applicable.',
    '核对期初余额及折算提示后点「建立账户」，记录系统分配的会计科目。' => 'Check the opening balance and conversion note, then Create account and record the assigned general-ledger account.',
    '回到列表检查原币余额、折 HKD 和科目，需要处理流水时点该行的「对账」。' => 'Back in the list, check the original-currency balance, HKD equivalent, and account. Select Reconcile on the row to process transactions.',
    '新账户按币种分组显示，关联科目和期初折算金额正确，对账入口可用。' => 'The new account appears under the correct currency with the right ledger account and opening conversion, and reconciliation is available.',
    '银行账户建立后不可删除，期初余额会生成分录；账号、币种和信用卡属性务必在建立前核对。' => 'Bank accounts cannot be deleted after creation, and opening balances create entries. Verify the account number, currency, and credit-card flag first.',
    '交易记录：按账户和匹配状态查看银行流水，并进入导入或对账。' => 'Bank transactions: filter transactions by account and match status, then import or reconcile them.',
    '先选择银行账户，再点「全部」「未匹配」或「已匹配」缩小检查范围。' => 'Choose a bank account, then All, Unmatched, or Matched to narrow the list.',
    '逐笔核对交易日期、摘要、收入和支出金额，优先处理未匹配流水。' => 'Check each transaction date, description, deposit, and withdrawal, prioritizing unmatched transactions.',
    '缺少月结单流水时点「导入流水」，完成文件解析和余额校验后返回。' => 'If statement transactions are missing, select Import transactions, complete file parsing and balance validation, then return.',
    '点「去对账」进入工作区，确认候选单据或选择对方科目录入。' => 'Select Go to reconciliation to confirm candidate documents or choose an offsetting account for entry.',
    '目标账户的流水完整，未匹配清单逐笔减少，已匹配记录能追到单据或分录。' => 'The account has complete transactions, unmatched items are cleared appropriately, and matched records trace to documents or entries.',
    '未匹配不等于错误，但月结前应查明；不要为了让清单归零而随意匹配金额相近的流水。' => 'Unmatched does not necessarily mean wrong, but investigate before close. Never match similar amounts arbitrarily just to clear the list.',
    '银行规则：按摘要关键词和收支方向建议对方科目，减少重复对账工作。' => 'Bank rules: suggest offsetting accounts from description keywords and transaction direction to reduce repetitive reconciliation.',
    '先从真实银行摘要中找出稳定关键词，并确定它应对应收入、支出和哪个对方科目。' => 'Find consistent keywords in real bank descriptions and determine the applicable direction and offsetting account.',
    '点「+ 新建规则」，填写「规则名称」「摘要包含」「方向」「对方科目」，再点「保存规则」。' => 'Select + New rule, enter the rule name, description keyword, direction, and offsetting account, then Save rule.',
    '回到列表核对匹配文本和科目，点「套用到未匹配流水」查看命中数量。' => 'Check the keyword and account in the list, then Apply to unmatched transactions to see the match count.',
    '到对账工作区逐笔确认建议；规则不再适用时点「删除」，避免以后误配。' => 'Confirm each suggestion in the reconciliation workspace. Delete obsolete rules to prevent future mismatches.',
    '规则列表显示正确关键词和命中数，未匹配流水得到可人工确认的建议。' => 'The rule list shows the correct keyword and match count, and unmatched transactions receive suggestions for manual confirmation.',
    '套用只给建议，不会自动记账；关键词过宽可能误命中，删除规则后不能恢复，应先核对命中记录。' => 'Applying rules only makes suggestions and never posts automatically. Broad keywords can mismatch transactions; deletion is irreversible, so review matches first.',
    '银行转账：登记两个同币种银行账户之间的资金调拨。' => 'Bank transfer: record a transfer between two bank accounts in the same currency.',
    '先准备银行扣款和入账记录，确认两个账户币种相同、金额和日期一致。' => 'Prepare the bank debit and credit records and confirm both accounts use the same currency, amount, and date.',
    '在「从」选择资金流出的账户，在「到」选择资金流入的账户。' => 'Under From, select the source account; under To, select the destination account.',
    '填写「金额」和「日期」，再次核对方向，避免把两个账户选反。' => 'Enter Amount and Date, then check the direction again to avoid reversing the accounts.',
    '点「确认转账」，随后到两个账户的交易记录或日记账核对对应凭证。' => 'Select Confirm transfer, then verify the voucher in both account transaction lists or the journal.',
    '转出账户余额减少、转入账户余额增加，并生成一张借贷相等的转账凭证。' => 'The source balance falls, the destination balance rises, and a balanced transfer voucher is generated.',
    '这里不支持跨币种兑换；确认后会实际记账，选反方向或重复提交都需另行更正。' => 'Currency exchange is not supported here. Confirmation posts the transfer; reversed accounts or duplicate submissions require separate corrections.',
    '期初余额：查看启用账套时各科目的结转余额和期初凭证。' => 'Opening balances: review carried-forward account balances and opening vouchers from ledger setup.',
    '先准备上一年度科目余额表，并确定期初日期及各币种折算依据。' => 'Prepare the prior-year trial balance and determine the opening date and currency-conversion basis.',
    '逐行核对「科目」「名称」「类别」「余额」，与结转资料逐项勾对。' => 'Check each account code, name, category, and balance against the carryforward records.',
    '检查页首借方、贷方和差额，差额为 0 才表示期初借贷平衡。' => 'Check total debits, credits, and Difference at the top. A zero difference means the opening entries balance.',
    '有「期初结转凭证」时核对凭证号、日期和金额；确需调整时点「手工补一笔」录入平衡分录。' => 'If an opening voucher exists, verify its number, date, and amount. For a necessary adjustment, select Add manual entry and enter a balanced journal.',
    '借方合计等于贷方合计、差额为 0，调整分录有清楚摘要和依据。' => 'Total debits equal credits, the difference is zero, and every adjustment has a clear description and supporting basis.',
    '本页不直接编辑既有期初数；调整会正式影响后续报表，不要用不平衡分录强行凑数。' => 'Existing opening figures are not edited directly here. Adjustments affect later reports; never force totals with an unbalanced entry.',

    // Inline help: guide through pending-rec
    '使用说明：按销售、采购、银行、会计和报表主题查阅完整操作指南。' => 'User guide: browse complete operating instructions by sales, purchases, banking, accounting, and reporting topics.',
    '先确定要处理的业务，再点「销售」「采购」「银行」「会计」或「报表」主题按钮。' => 'Identify the business task, then select the Sales, Purchases, Banking, Accounting, or Reports topic.',
    '从主题的流程说明找到当前环节，点相关页面链接进入对应功能。' => 'Find the current stage in the topic workflow and follow its page link to the relevant function.',
    '录单前查看字段解释，按说明准备往来单位、日期、币种、科目和附件。' => 'Before entering a document, read the field guidance and prepare the counterparty, date, currency, accounts, and attachments.',
    '遇到状态时先查常见问题，再回到原单据核对；处理完可返回本页继续下一主题。' => 'For status issues, check the FAQs and then review the original document. Return here for the next topic when finished.',
    '你已打开与当前业务相符的主题，并能通过流程链接到达正确功能页。' => 'You have opened the topic for the current task and can reach the correct function through its workflow links.',
    '指南只提供操作说明，不会保存或修改账簿；涉及过账、锁账和删除时仍要以单据页面的确认提示为准。' => 'The guide provides instructions only and never saves or changes the ledger. Follow the document confirmation prompts for posting, locking, and deletion.',
    '导入月结单：先看已导入列表，再进入独立上传界面；确认识别结果后才写入。' => 'Import statement: review the imported list, then open a dedicated upload screen; nothing is written until you confirm the parsed result.',
    '先准备 CSV、XLSX、XLS 或 PDF 月结单，文件不超过 20MB。' => 'Prepare a CSV, XLSX, XLS, or PDF statement no larger than 20 MB.',
    '点右上角「＋ 导入月结单」进入上传界面，选择银行账户与文件后点「上传并解析」。' => 'Select Import statement at the top right to open the upload screen, choose the bank account and file, then select Upload and parse.',
    '识别内容显示在下方，逐笔检查预览，并核对「期初 + 存入 − 支出 = 期末」的算术校验。' => 'The parsed rows appear below. Check every preview row and verify Opening + deposits - withdrawals = Closing.',
    '确认无误后点「导入并校验」，在确认框中确认才写入系统；完成后返回列表可查看或下载原始文件。' => 'After checking, select Import and validate and confirm in the dialog before anything is posted; then return to the list to view or download the original file.',
    '导入结果显示流水笔数且余额勾稽通过，交易记录中能查到这批流水。' => 'The import result shows the transaction count and a successful balance check, and the transactions appear in the transaction list.',
    '同一文件会被识别并拒绝重复导入；解析成功不代表分类正确，导入后仍须逐笔对账。' => 'Duplicate files are detected and rejected. Successful parsing does not confirm correct classification; reconcile every transaction after import.',
    '对账工作区：把银行流水匹配到业务单据，或为无单据流水直接入账。' => 'Reconciliation workspace: match bank transactions to business documents or enter transactions without documents directly.',
    '先选择银行账户并点一笔未匹配流水，核对它的日期、摘要、收支方向和金额。' => 'Select a bank account and an unmatched transaction, then check its date, description, direction, and amount.',
    '查看系统候选单据，确认往来单位、币种和金额后点「确认匹配」。' => 'Review candidate documents, confirm the counterparty, currency, and amount, then select Confirm match.',
    '确实没有业务单据时点「无单据：直接入账」，选择正确的「对方科目」并点「确认入账」。' => 'If no business document exists, select No document: enter directly, choose the correct offsetting account, and select Confirm entry.',
    '跨币种匹配时填写明确原因，完成后到「交易记录」复查匹配状态和生成分录。' => 'Provide a clear reason for cross-currency matches, then review the match status and generated entry under Bank transactions.',
    '已处理流水显示已匹配或已入账，关联单据余额与会计分录可正常追查。' => 'Processed transactions show Matched or Entered, and linked document balances and accounting entries remain traceable.',
    '不要为了清零而硬配金额相近的流水；直接入账会生成正式分录，跨币种原因和汇兑差额必须真实。' => 'Never force similar amounts to match just to clear the list. Direct entry creates a posted journal; cross-currency reasons and exchange differences must be genuine.',
    '会计科目：维护账套分类骨架，决定凭证和报表如何归集。' => 'Chart of accounts: maintain the ledger classification structure that determines how vouchers and reports are grouped.',
    '先点「显示停用科目」或「只看启用科目」确定查看范围，再按代码和类别找目标科目。' => 'Select Show inactive accounts or Active accounts only to set the scope, then find the account by code and category.',
    '管理员新增时点「＋ 新增科目」，准备不重复的代码、名称、类别和正常余额方向。' => 'To add an account, an administrator selects + New account and prepares a unique code, name, category, and normal balance.',
    '选择父科目及报表归类后点「保存」，回到科目树检查层级和汇总位置。' => 'Choose the parent account and report classification, Save, then check its hierarchy and subtotal position in the account tree.',
    '不再使用的科目可点「停用」；若提示已有分录，保留科目并停止用于新业务。' => 'Select Deactivate for an unused account. If entries already exist, retain the account and stop using it for new transactions.',
    '新科目代码、类别、正常余额和父级正确，建单及手工分录中可以选用。' => 'The new account has the correct code, category, normal balance, and parent, and is available on documents and manual journals.',
    '已被分录使用的科目不要随意改代码或类别；有 postings（记账记录）的科目不能停用，以免破坏历史报表。' => 'Do not casually change the code or category of an account used in entries. Accounts with postings cannot be deactivated, preserving historical reports.',
    '日记账：查询全部业务和手工凭证，查看明细、附件、冲销或打印。' => 'Journal: search all business and manual vouchers, then view details and attachments, reverse, or print them.',
    '点「附件」可上传、查看或删除该分录的附件；单文件上限 20MB，审计角色只读。' => 'Select Attachments to upload, view, or delete files for the entry. The limit is 20 MB per file and auditors have read-only access.',
    '先在搜索框输入分录号、摘要或来源条件，确定要检查的日期和凭证范围。' => 'Search by entry number, description, or source, and set the date and voucher range to review.',
    '点「明细」或分录号，逐行核对科目、摘要、借方、贷方和来源单据。' => 'Select Details or the entry number, then check each account, description, debit, credit, and source document.',
    '草稿需要修改时点「编辑草稿」；确认无用的草稿才删除。' => 'Select Edit draft to correct a draft. Delete only drafts confirmed to be unnecessary.',
    '已过账凭证有错时点「冲销」生成反向分录；需要纸质记录时点「打印本页凭证」。' => 'To correct a posted voucher, select Reverse to create a reversing entry. Select Print vouchers on this page for paper records.',
    '分录详情' => 'Journal Entry',
    '本页' => 'On this page',
    '分录信息' => 'Entry information',
    '分录明细' => 'Entry lines',
    '制单' => 'Prepared by',
    '冲销原因' => 'Reversal reason',
    '确认冲销这张凭证？' => 'Reverse this voucher?',
    '冲销会生成一张反向分录，原凭证保留；日期与期间必须正确。' => 'Reversal creates a reversing entry and keeps the original voucher. The date and period must be correct.',
    '这张凭证已被冲销：' => 'This voucher has been reversed:',
    '这是一张冲销分录，原凭证为：' => 'This is a reversing entry. Original voucher:',
    '目标凭证借贷平衡且来源清楚，冲销后能看到原凭证与反向凭证的关联。' => 'The target voucher balances and has a clear source; after reversal, the original and reversing vouchers are linked.',
    '冲销（用相反借贷抵回原凭证）不会抹掉历史；过账凭证不可编辑或删除，冲销日期和期间必须正确。' => 'Reversal offsets the original voucher with opposite debits and credits without erasing history. Posted vouchers cannot be edited or deleted; use the correct reversal date and period.',
    '手工分录：用于计提、调账和更正，直接录入借贷行。' => 'Manual journal: enter debit and credit lines directly for accruals, adjustments, and corrections.',
    '先准备调整依据、凭证日期、币种和科目余额，写清楚为什么需要手工处理。' => 'Prepare the adjustment basis, voucher date, currency, and account balances, and document why manual treatment is needed.',
    '填写摘要、分录号和日期，在每一行选择科目并输入借方或贷方金额。' => 'Enter the description, entry number, and date. Select an account and enter a debit or credit amount on each line.',
    '行数不够时点「＋ 添加一行」，检查借方合计等于贷方合计且每行方向正确。' => 'Select + Add line when more rows are needed. Confirm total debits equal total credits and every line has the correct direction.',
    '新分录确认后点「保存并过账」；编辑已有草稿时点「保存草稿」，随后回日记账复核。' => 'For a verified new entry, select Save and post. When editing an existing draft, select Save draft, then review it in the journal.',
    '系统接受平衡分录并显示分录号，过账后各科目余额和报表相应更新。' => 'The system accepts the balanced entry and shows its number; posting updates account balances and reports accordingly.',
    '手工分录没有业务单据自动控制，必须附充分依据；过账后不能直接改，错误应另做冲销。' => 'Manual journals lack the automatic controls of business documents and require sufficient support. Posted entries cannot be edited directly; reverse errors separately.',
    '期末重估：按期末汇率调整外币账户的港币账面价值。' => 'Period-end revaluation: adjust the HKD carrying value of foreign-currency accounts using closing exchange rates.',
    '先填写「期间（YYYY-MM）」，确认要重估的月份和该期末日期。' => 'Enter Period (YYYY-MM) and confirm the month to revalue and its period-end date.',
    '到「汇率维护」检查相关外币的期末真实汇率，并核对外币账户余额。' => 'Under Exchange rates, check the actual closing rates for the relevant currencies and verify the foreign-currency account balances.',
    '回到本页点「执行重估」，查看系统生成或更新的重估结果。' => 'Return here and select Run revaluation, then review the results generated or updated by the system.',
    '到「日记账」按期间和摘要找到重估分录，核对汇兑损益及外币账户折 HKD 余额。' => 'Find the revaluation entry in the Journal by period and description, then verify exchange gains or losses and foreign-currency account balances in HKD.',
    '本期重估分录存在且借贷平衡，外币账户按期末汇率折算后的余额正确。' => 'The current revaluation entry exists and balances, and foreign-currency accounts convert correctly at closing rates.',
    '重估会正式生成会计分录并影响汇兑损益；同一期间重复执行是幂等的，不会重复计提，但汇率或期间填错仍需冲销更正。' => 'Revaluation creates posted entries and affects exchange gains or losses. Repeating it in the same period is idempotent, but incorrect rates or periods still require reversal and correction.',
    '汇率维护：保存外币折算所用的日期、币对和真实汇率。' => 'Exchange rates: save the dates, currency pairs, and actual rates used for foreign-currency conversion.',
    '先准备银行成交汇率或可靠来源，明确日期、源币种、目标币种和换算方向。' => 'Prepare an executed bank rate or another reliable source, and identify the date, source currency, target currency, and conversion direction.',
    '填写「日期」「源币种」「目标币种」「汇率」，核对方向后点「保存汇率」。' => 'Enter Date, Source currency, Target currency, and Rate, check the direction, then select Save rate.',
    '在列表检查新记录及回退标记，确认系统取到的日期和汇率符合预期。' => 'Check the new record and fallback flag in the list, confirming the system uses the expected date and rate.',
    '查看自动更新信息，再打开一张相关外币单据或期末重估，验证折算结果。' => 'Review the automatic update information, then open a related foreign-currency document or period-end revaluation to verify conversion.',
    '列表能查到正确日期和币对的汇率，外币单据的港币折算与该汇率一致。' => 'The list shows the rate for the correct date and currency pair, and foreign-currency documents convert to HKD at that rate.',
    '源币种与目标币种选反会导致严重折算错误；页面没有单独编辑按钮，更正后重新保存并核对列表，不得使用估算汇率。' => 'Reversing the source and target currencies causes serious conversion errors. There is no separate edit button; save the correction again and check the list. Never use estimated rates.',
    '期间锁定：禁止已结账月份继续写入分录，并保留解锁记录。' => 'Period locks: prevent further entries in closed months and retain unlock records.',
    '先选择要处理的期间，确认该期对账、重估、报表和复核均已完成。' => 'Select the period and confirm that reconciliation, revaluation, reporting, and review are complete.',
    '填写「期间」和「备注」，点「锁定期间」，在确认提示中再次核对月份。' => 'Enter Period and Notes, select Lock period, and check the month again in the confirmation prompt.',
    '查看锁定状态历史，并尝试理解锁定后该期间的新记账和冲销都会被阻止。' => 'Review the lock status history. Once locked, new postings and reversals in that period are blocked.',
    '确需更正时填写原因并点「解锁期间」，处理完后重新检查报表并再次锁定。' => 'For a necessary correction, enter the reason and select Unlock period. Afterward, recheck reports and lock the period again.',
    '期间状态与操作一致，锁定历史中有本次操作人、时间和备注。' => 'The period status matches the action, and lock history records its user, time, and notes.',
    '锁定会阻止该期间写入；解锁会留下审计痕迹，不能把它当作日常改账捷径，已关闭期间应在后续期间调整。' => 'Locking blocks entries in the period. Unlocking leaves an audit trail and is not a routine editing shortcut; adjust closed periods in a later period.',
    '待复核：处理系统发现的阻断项和警告，让单据具备继续过账的条件。' => 'Pending review: resolve system-detected blockers and warnings so documents can proceed to posting.',
    '先按单据号和来源选择一条待办，区分红色阻断项与一般警告。' => 'Select an item by document number and source, distinguishing red blockers from general warnings.',
    '打开原单据详情，核对缺失附件、外币汇率、借贷或其他校验原因。' => 'Open the source document and check missing attachments, foreign-exchange rates, debits and credits, or other validation issues.',
    '问题已补正后回到对应项目点「确认」，再刷新查看是否仍有阻断。' => 'After correcting the issue, return to the item and select Confirm. Refresh to check whether any blockers remain.',
    '仅对有充分依据且确认可接受的警告点「忽略」，并在原单据保留支持资料。' => 'Select Ignore only for warnings that are sufficiently supported and acceptable, and retain supporting evidence on the source document.',
    '已处理项目从待办消失，原单据校验通过并能进入下一道复核或过账流程。' => 'Resolved items leave the pending list, and the source document passes validation and can proceed to review or posting.',
    '本页处理的是系统复核发现，不等同于「复核队列」的人工批准；忽略警告不会修正原始错误，阻断项不能强行跳过。' => 'This page handles system review findings, not manual approval in Review queue. Ignoring a warning does not fix its cause, and blockers cannot be bypassed.',
    '复核队列：提交待审单据，由复核人批准或写明原因退回。' => 'Review queue: submit documents for review so a reviewer can approve them or return them with reasons.',
    '先按单号、往来单位和日期选择要处理的单据，确认附件与明细已经齐全。' => 'Select a document by number, counterparty, and date, and confirm its attachments and details are complete.',
    '打开原单据逐项核对金额、币种、科目和原始凭证，再返回队列。' => 'Open the source document, check each amount, currency, account, and original voucher, then return to the queue.',
    '自己的草稿需要送审时点「提交复核」，确认状态进入待复核。' => 'To submit your own draft for review, select Submit for review and confirm its status changes to Pending review.',
    '复核人核对后点「批准」；有问题时在「备注 / 退回原因」写清修改要求并点「退回」。' => 'After checking, the reviewer selects Approve. For issues, enter the required changes under Notes / Return reason and select Return.',
    '单据显示已批准或已退回及对应复核人，退回单据能看到明确原因。' => 'The document shows Approved or Returned with its reviewer, and returned documents have a clear reason.',
    '批准是过账前的重要控制，不能代替金额核对；退回后须修改并重新提交，不要用空备注反复退回。' => 'Approval is a key pre-posting control but does not replace amount checks. Correct and resubmit returned documents; never return them repeatedly with blank notes.',

    // Inline help: report-tb through report-tax
    '试算表：按截止日汇总全部科目借贷和余额，检查账簿是否平衡。' => 'Trial balance: summarize debits, credits, and balances for every account as of a date to check ledger balance.',
    '先在期间栏选择截止日期并应用，准备同一日期的科目余额资料。' => 'Select and apply the cutoff date in the period bar, and prepare account balance records for the same date.',
    '逐行核对科目代码、名称、借方、贷方和余额，异常科目到总分类账追查。' => 'Check each account code, name, debit, credit, and balance, tracing unusual accounts to the general ledger.',
    '查看底部「合计」是否显示平衡，并确认借方合计等于贷方合计、差额为 0。' => 'Check whether Total at the bottom shows balanced, with total debits equal to total credits and a zero difference.',
    '需要留档时使用页头「导出 PDF」选择语言，下载后核对截止日。' => 'For records, use Export PDF in the header to choose a language, then verify the cutoff date after download.',
    '试算表显示平衡且差额为 0，PDF 的期间和科目合计与页面一致。' => 'The trial balance shows balanced with zero difference, and the PDF period and account totals match the page.',
    '本表按截止日取数，起始日期不会改变该时点余额；只统计已过账分录，不平衡时不要对外出报表。' => 'This report uses the cutoff date; a start date does not change balances at that point. Only posted entries count. Do not issue reports externally while unbalanced.',
    '账户类型摘要：按科目类型汇总所选期间的本期借贷发生额。' => 'Account type summary: summarize current-period debit and credit activity by account type for the selected period.',
    '先设置起止日期，准备需要分析的财务期间。' => 'Set the start and end dates for the financial period to analyze.',
    '点「应用」刷新表格，确认页面期间与所选区间一致。' => 'Select Apply to refresh the table and confirm the page period matches the selected range.',
    '逐组查看账户类型及包含的科目代码，核对借方和贷方发生额。' => 'Review each account type and its account codes, checking debit and credit activity.',
    '检查底部合计后点「导出 PDF」，选择语言并核对导出期间。' => 'Check the totals at the bottom, select Export PDF, choose a language, and verify the exported period.',
    '各类型合计与底部借方、贷方总额一致，PDF 使用相同起止日期。' => 'The account type subtotals reconcile to total debits and credits at the bottom, and the PDF uses the same date range.',
    '这里看的是期间发生额而非单一时点余额；科目类别设置错误会影响分组，应先到会计科目页更正。' => 'This report shows period activity rather than balances at one date. Incorrect account categories affect grouping and should first be corrected in the chart of accounts.',
    '详细的总分类账：逐科查看期初、每笔借贷、滚动余额和期末。' => 'Detailed general ledger: review opening balances, every debit and credit, running balances, and closing balances by account.',
    '先设置起止日期；只查一个科目时填写「科目代码（可不填）」，查全部则留空。' => 'Set the start and end dates. Enter Account code (optional) for one account or leave it blank for all accounts.',
    '点「应用」，确认每个科目块都以正确的「期初余额」开始。' => 'Select Apply and confirm each account section starts with the correct Opening balance.',
    '逐行核对日期、交易明细、凭证号、借项、贷项和余额，并用凭证号回查日记账。' => 'Check each date, transaction detail, voucher number, debit, credit, and balance, using voucher numbers to trace back to the journal.',
    '检查「本期合计」与「期末余额」的勾稽，再点「导出 PDF」留档。' => 'Verify that Current-period total reconciles to Closing balance, then Export PDF for records.',
    '期初加本期借贷变动能勾稽到期末，筛选科目和日期与页面标题一致。' => 'Opening balance plus current-period debit and credit movements reconciles to closing, and the account and date filters match the page title.',
    '余额方向要结合科目性质理解，不能看到负数就认定错误；本页只包含有分录的科目和已过账数据。' => 'Interpret balance direction by account nature; a negative amount is not automatically an error. This page includes only accounts with entries and posted data.',
    '损益表：查看所选期间收入、成本、费用、税项和本期溢利。' => 'Profit and loss: review income, costs, expenses, tax, and profit for the selected period.',
    '先设置起止日期并应用，确认比较列使用「上一财务年度」或「上年同期」的口径。' => 'Set and apply the start and end dates, and confirm whether comparison columns use Previous financial year or Same period last year.',
    '逐节核对收入、销售成本、其他收入、经营费用、财务费用和税项。' => 'Check each section for revenue, cost of sales, other income, operating expenses, finance costs, and tax.',
    '检查毛利、除税前溢利和本期溢利，并对异常「变动」金额到总分类账追查。' => 'Review gross profit, profit before tax, and profit for the period, tracing unusual Movement amounts to the general ledger.',
    '需要留档时使用页头「导出 PDF」，选择语言并核对本期及比较期间。' => 'For records, use Export PDF in the header, choose a language, and verify the current and comparative periods.',
    '各级小计能勾稽到本期溢利，比较期间和变动金额符合所选口径。' => 'Subtotals reconcile to profit for the period, and comparative periods and movements follow the selected basis.',
    '括号通常表示成本、费用或负方向，不是另一套金额；草稿不计入，公司年结日会影响上一财务年度比较。' => 'Parentheses usually indicate costs, expenses, or negative direction, not separate amounts. Drafts are excluded, and the company year-end affects prior-financial-year comparisons.',
    '财务状况表：查看截止日的资产、负债、权益及平衡关系。' => 'Statement of financial position: review assets, liabilities, equity, and their balance as of a date.',
    '先在期间栏选择截止日期并应用，准备同一时点的银行和往来余额资料。' => 'Select and apply the cutoff date in the period bar, and prepare bank and counterparty balances for the same date.',
    '逐节核对资产、负债和权益下的科目，注意重分类及累计损益列示。' => 'Check the accounts under assets, liabilities, and equity, noting reclassifications and accumulated profit or loss presentation.',
    '查看底部「资产 −（负债+权益）」是否显示平衡，差额应为 0。' => 'Check whether Assets - (Liabilities + Equity) at the bottom shows balanced, with zero difference.',
    '不平衡时到试算表和总分类账追查；平衡后用页头「导出 PDF」留档。' => 'If unbalanced, investigate through the trial balance and general ledger. Once balanced, use Export PDF in the header for records.',
    '资产合计等于负债加权益，差额为 0，PDF 截止日期与页面一致。' => 'Total assets equal liabilities plus equity, the difference is zero, and the PDF cutoff date matches the page.',
    '这是时点快照，起始日期不改变截止日余额；不平衡不能直接对外出具，草稿也不会计入。' => 'This is a point-in-time snapshot; a start date does not change cutoff balances. Do not issue an unbalanced statement externally. Drafts are excluded.',
    '现金流量表：用间接法解释期初现金如何变动到期末现金。' => 'Cash flow statement: use the indirect method to explain the movement from opening to closing cash.',
    '先设置起止日期并应用，准备同期银行余额和损益表。' => 'Set and apply the start and end dates, and prepare bank balances and the profit and loss statement for the same period.',
    '从「期初现金及现金等价物」和本期净利开始，核对非现金调整及营运资金变动。' => 'Start with Opening cash and cash equivalents and net profit for the period, then check non-cash adjustments and working-capital movements.',
    '分别检查经营、投资和融资活动净额，确认现金净变动的计算。' => 'Review net operating, investing, and financing activities separately and verify the net cash movement calculation.',
    '将「期末现金余额」与财务状况表及银行余额核对，再用页头「导出 PDF」留档。' => 'Reconcile Closing cash balance to the statement of financial position and bank balances, then use Export PDF in the header for records.',
    '期初现金加现金净变动等于期末现金，且与财务状况表现金一致。' => 'Opening cash plus net cash movement equals closing cash and agrees with cash in the statement of financial position.',
    '间接法（从净利调整出现金流）不等于逐笔银行流水；科目归类或期初分录异常会影响分类，应先追查再导出。' => 'The indirect method derives cash flow by adjusting net profit and is not a transaction-by-transaction bank listing. Account classification or opening-entry issues affect categories; investigate before export.',
    '账龄分析：按币种和账龄区间查看未收应收或未付应付。' => 'Aging analysis: review outstanding receivables or unpaid payables by currency and aging band.',
    '先选择截止日期，再点「应收账龄」或「应付账龄」确定查看方向。' => 'Select the cutoff date, then Receivables aging or Payables aging to set the direction.',
    '按币种查看 0-30、31-60、61-90 和 90+ 各档，优先关注长账龄金额。' => 'Review the 0-30, 31-60, 61-90, and 90+ bands by currency, focusing first on older balances.',
    '核对「原币合计」与「折 HKD」，并到核销工作台打开相关发票或账单。' => 'Check Original-currency total against HKD equivalent, and open related invoices or bills in the allocation workspace.',
    '根据结果安排催收或付款，需要留档时使用页头「导出 PDF」。' => 'Use the results to plan collection or payment, and Export PDF in the header when records are needed.',
    '各账龄档之和等于原币合计，列表方向、截止日和港币折算正确。' => 'The aging bands sum to the original-currency total, with the correct direction, cutoff date, and HKD conversion.',
    '不同币种不要直接相加原币金额；账龄只是风险线索，催收或付款前应核对原单到期日和核销记录。' => 'Never add original-currency amounts across currencies. Aging is only a risk indicator; check source due dates and allocations before collection or payment.',
    '银行账户余额表：查看各账户当前原币余额及折港币合计。' => 'Bank account balances: review current original-currency balances by account and their total HKD equivalents.',
    '先准备同一时点的银行对账单，并确定要核对的账户和币种。' => 'Prepare bank statements for the same date and identify the accounts and currencies to reconcile.',
    '逐行检查账户、币种、原币余额和折 HKD，外币账户同时核对采用汇率。' => 'Check each account, currency, original-currency balance, and HKD equivalent, including the rates used for foreign-currency accounts.',
    '查看「HKD 折算合计」，与银行相关总账科目和实际可用资金交叉核对。' => 'Review Total HKD equivalent and cross-check it against bank general-ledger accounts and actual available funds.',
    '发现差异先到交易记录和对账工作区处理；需要留档时使用页头「导出 PDF」。' => 'Resolve differences through Bank transactions and the reconciliation workspace first. Use Export PDF in the header for records.',
    '每个账户原币与折算余额可追查，港币合计与总账银行余额勾稽一致。' => 'Each original-currency and converted balance is traceable, and the HKD total reconciles to general-ledger bank balances.',
    '当前实现读取最新账户余额，上方期间选择器不会改变结果；账面余额与银行实际余额差异必须查明。' => 'The current implementation reads the latest account balances; the period selector above does not change results. Investigate every difference between book and actual bank balances.',
    '汇兑损益表：汇总外币业务产生的已实现和未实现汇兑结果。' => 'Exchange gains and losses: summarize realized and unrealized foreign-exchange results from foreign-currency transactions.',
    '先准备外币账户、收付款和期末重估资料，确定要追查的币种及凭证。' => 'Prepare foreign-currency account, receipt, payment, and period-end revaluation records, and identify the currencies and vouchers to trace.',
    '逐行查看汇兑项目，区分已收付结算产生与期末折算产生的金额。' => 'Review each exchange item, distinguishing amounts from receipt or payment settlement from period-end conversion.',
    '核对合计，并通过相关收付款、重估分录和总分类账追查异常数字。' => 'Check the totals and trace unusual figures through related receipts, payments, revaluation entries, and the general ledger.',
    '需要留档时使用页头「导出 PDF」，下载后核对币种和合计。' => 'For records, use Export PDF in the header, then verify currencies and totals after download.',
    '各行能汇入汇兑损益合计，异常项目都能追溯到具体凭证或重估记录。' => 'All rows reconcile to total exchange gains or losses, and unusual items trace to specific vouchers or revaluation records.',
    '当前实现未把上方起止日期传给汇兑接口，不要把它当作已按期间筛选；已实现与未实现损益不要重复相加解释。' => 'The current implementation does not pass the dates above to the exchange interface, so results are not period-filtered. Do not double-count realized and unrealized results in the analysis.',
    '利得税计算表：在会计利润上列示税务调整，计算应评税利润和税额。' => 'Profits tax computation: present tax adjustments to accounting profit and calculate assessable profits and tax payable.',
    '先用上方期间选择器确定「基期止」，并检查两级制资格是否已经确定。' => 'Use the period selector above to set Basis period end, and check whether two-tier eligibility has been determined.',
    '核对会计利润后，在「新增税务调整」选择「类别」，填写「项目名称」「金额」「依据」并点「添加调整项」。' => 'After checking accounting profit, select Category under New tax adjustment, enter Item, Amount, and Basis, then Add adjustment.',
    '逐项检查加回、扣除和资本免税额；录错的调整项点该行「删除」后重新添加。' => 'Check each add-back, deduction, and capital allowance. For an incorrect adjustment, Delete its row and add it again.',
    '检查经调整的应评税利润、两级税率及应补缴金额，再用导出菜单下载 PDF。' => 'Review adjusted assessable profits, two-tier rates, and the additional amount payable, then download the PDF from the export menu.',
    '调整项均有金额和依据，应评税利润与税额勾稽一致，PDF 基期止正确。' => 'Every adjustment has an amount and basis, assessable profits reconcile to tax, and the PDF shows the correct basis period end.',
    '资格未确定时不会计算税额；税务调整不等于会计分录，删除会改变计算结果，最终申报应由专业人士复核。' => 'Tax is not calculated until eligibility is determined. Tax adjustments are not accounting entries, and deletion changes the computation. A professional should review the final filing.',

    // Inline help: report-statements through report-purchase
    '财务报表：一次查看财务状况、损益、权益变动、现金流量和附注。' => 'Financial statements: review financial position, profit and loss, changes in equity, cash flows, and notes together.',
    '先设置起止日期并应用，准备同期试算表、银行余额和税务资格资料。' => 'Set and apply the start and end dates, and prepare the trial balance, bank balances, and tax eligibility records for the same period.',
    '用章节导航依次打开「财务状况表」「损益及全面收益」「权益变动」「现金流量」和「附注」。' => 'Use section navigation to open Financial position, Profit or loss and comprehensive income, Changes in equity, Cash flows, and Notes in sequence.',
    '检查资产负债平衡、权益与损益勾稽、期末现金等 PASS 结果，并阅读主要会计政策。' => 'Check PASS results for the accounting balance, equity-to-profit reconciliation, closing cash, and other checks, and read the significant accounting policies.',
    '在各章节点「导出 PDF」取单张报表，或在权益变动章节导出完整报表包。' => 'Select Export PDF in a section for an individual statement, or export the complete statement package from Changes in equity.',
    '各表期间一致且勾稽检查通过，附注中的报告基础与公司实际设置一致。' => 'All statements use the same period and pass reconciliation checks, and the reporting basis in the notes matches the company settings.',
    '报表只包含已过账分录；任何不平衡或勾稽异常都应先查明，不要直接对外提供完整报表包。' => 'Statements include posted entries only. Investigate every imbalance or reconciliation exception before issuing the complete package externally.',
    '财务比率表：查看流动性和盈利能力指标及其公式、计算基础。' => 'Financial ratios: review liquidity and profitability indicators with their formulas and calculation bases.',
    '先准备当前财务状况表和损益表，确定要分析的资产、负债、收入及往来余额。' => 'Prepare the current statement of financial position and profit and loss statement, identifying the assets, liabilities, income, and counterparty balances to analyze.',
    '逐行阅读「比率」「数值」「计算式」「单位」，区分百分比与倍数。' => 'Read each Ratio, Value, Formula, and Unit, distinguishing percentages from multiples.',
    '在「计算基础」核对总资产、总负债、收入、流动资产和应收应付等输入值。' => 'Under Calculation basis, verify inputs such as total assets, total liabilities, income, current assets, receivables, and payables.',
    '异常比率回到对应报表和总分类账追查，再用页头「导出 PDF」保存结果。' => 'Trace unusual ratios to the relevant statements and general ledger, then use Export PDF in the header to save the results.',
    '每个比率都能用计算基础复算，单位、公式和异常原因均已确认。' => 'Every ratio can be recalculated from its basis, with units, formulas, and reasons for exceptions confirmed.',
    '当前实现未把上方期间参数传给比率接口，不要声称已按所选日期筛选；比率只是分析线索，不能替代明细核查。' => 'The current implementation does not pass the period parameters above to the ratio interface, so results are not filtered by the selected dates. Ratios are analytical indicators and do not replace detailed review.',
    '客户余额表：按客户和币种查看未收发票余额及港币折算。' => 'Customer balances: review outstanding invoice balances and HKD equivalents by customer and currency.',
    '先准备客户对账资料，确定要核对的客户、币种和未结发票。' => 'Prepare customer reconciliation records and identify the customers, currencies, and open invoices to check.',
    '逐行检查客户、原币未收金额和折 HKD，优先核对余额较大的客户。' => 'Check each customer, original-currency outstanding amount, and HKD equivalent, prioritizing larger balances.',
    '把合计与「核销工作台」的应收未收及相关发票详情逐张勾对。' => 'Reconcile the totals to outstanding receivables in the Allocation workspace and to each related invoice detail.',
    '发现差异先检查收款核销和贷记单，再用页头「导出 PDF」保存对账结果。' => 'For differences, check receipt allocations and credit notes first, then use Export PDF in the header to save the reconciliation.',
    '客户余额与未结发票逐张一致，各币种原币和港币合计均已核对。' => 'Customer balances agree with each open invoice, and original-currency and HKD totals are verified for every currency.',
    '当前实现未按上方起止日期过滤接口结果，不要把表格当作历史时点余额；不同币种原币不可直接相加。' => 'The current implementation does not filter interface results by the dates above, so this is not a historical point-in-time balance. Never add original-currency amounts across currencies.',
    '供应商余额表：按供应商和币种查看未付账单余额及港币折算。' => 'Vendor balances: review unpaid bill balances and HKD equivalents by vendor and currency.',
    '先准备供应商对账单，确定要核对的供应商、币种和未结账单。' => 'Prepare vendor statements and identify the vendors, currencies, and open bills to check.',
    '逐行检查供应商、原币未付金额和折 HKD，留意逾期或异常大额余额。' => 'Check each vendor, original-currency unpaid amount, and HKD equivalent, noting overdue or unusually large balances.',
    '把合计与「核销工作台」的应付未付及相关账单详情逐张勾对。' => 'Reconcile the totals to outstanding payables in the Allocation workspace and to each related bill detail.',
    '发现差异先检查付款核销和贷记单，再用页头「导出 PDF」保存对账结果。' => 'For differences, check payment allocations and credit notes first, then use Export PDF in the header to save the reconciliation.',
    '供应商余额与未结账单逐张一致，各币种原币和港币合计均已核对。' => 'Vendor balances agree with each open bill, and original-currency and HKD totals are verified for every currency.',
    '当前实现未按上方起止日期过滤接口结果，不要把表格当作历史时点余额；付款前仍要核对账单和银行账户。' => 'The current implementation does not filter interface results by the dates above, so this is not a historical point-in-time balance. Verify bills and the bank account before payment.',
    '总分类账：按期间和科目汇总发生额，并可下钻逐笔明细。' => 'General ledger: summarize activity by period and account, with drill-down to individual entries.',
    '先设置起止日期，在科目下拉框选择「全部科目汇总」或一个具体科目。' => 'Set the start and end dates, then choose Summary of all accounts or a specific account from the account list.',
    '点「查看」；汇总状态逐行核对科目、类别、借方、贷方和余额。' => 'Select View. In summary mode, check each account, category, debit, credit, and balance.',
    '点目标行的「明细」，检查正常余额方向、期初到期末的逐笔分录和滚动余额。' => 'Select Details on the target row to review normal balance direction, individual entries from opening to closing, and running balances.',
    '用分录号回查日记账，确认异常后用页头「导出 PDF」保存当前账目。' => 'Trace entry numbers back to the journal, resolve exceptions, then use Export PDF in the header to save the current ledger.',
    '汇总借贷与明细发生额一致，期末余额能由逐笔记录勾稽出来。' => 'Summary debits and credits agree with detailed activity, and individual records reconcile to the closing balance.',
    '正常余额方向（科目通常增加的一方）有助于识别异常负数；汇总与明细要使用相同期间和科目。' => 'Normal balance direction, the side on which an account usually increases, helps identify unusual negatives. Use the same period and account for summary and detail.',
    '日记簿：按日期顺序列出全部会计分录，便于逐日检查。' => 'Daybook: list all accounting entries in date order for daily review.',
    '先在自己的「from」「to」日期框输入起止日期，确定要检查的区间。' => 'Enter the start and end dates in this page’s own From and To fields to set the review range.',
    '点「筛选」，核对结果是否只包含目标日期的分录。' => 'Select Filter and confirm the results include only entries within the target dates.',
    '逐行检查来源、摘要、状态和借方合计，点分录号打开日记账明细。' => 'Check each source, description, status, and total debits, then select an entry number to open its journal details.',
    '发现异常回到原单据或凭证处理，再用页头「导出 PDF」保存日记簿。' => 'Resolve exceptions in the source document or voucher, then use Export PDF in the header to save the daybook.',
    '日期区间正确，每笔分录都能打开并核对其借贷明细和来源。' => 'The date range is correct, and every entry opens for verification of its debit and credit details and source.',
    '本页有自己的日期筛选框；借方合计不是利润，草稿与已过账状态要分开判断，不要在日记簿直接改数。' => 'This page has its own date filters. Total debits are not profit; assess draft and posted statuses separately, and never edit figures directly in the daybook.',
    '销售明细表：按客户和币种汇总销售发票数据，用于销售核对。' => 'Sales detail: summarize sales invoice data by customer and currency for sales reconciliation.',
    '先准备销售发票列表和客户对账资料，确定要核对的客户及币种。' => 'Prepare the sales invoice list and customer reconciliation records, identifying the customers and currencies to check.',
    '逐行查看客户和币种分组，核对发票金额、合计及港币折算口径。' => 'Review each customer and currency group, checking invoice amounts, totals, and the HKD conversion basis.',
    '把异常客户或币种与发票列表、贷记单和收款核销记录交叉检查。' => 'Cross-check unusual customers or currencies against the invoice list, credit notes, and receipt allocations.',
    '确认合计后使用页头「导出 PDF」，选择语言保存销售明细。' => 'After verifying the totals, use Export PDF in the header and choose a language to save the sales detail.',
    '客户及币种合计能与发票和贷记单记录勾稽，PDF 与页面数字一致。' => 'Customer and currency totals reconcile to invoice and credit-note records, and PDF figures match the page.',
    '当前实现未把上方起止日期传给销售报表接口，不要当作已按期间筛选；销售额不等于已收款。' => 'The current implementation does not pass the dates above to the sales report interface, so results are not period-filtered. Sales do not equal receipts.',
    '采购明细表：按供应商和币种汇总采购账单数据，用于采购核对。' => 'Purchase detail: summarize purchase bill data by vendor and currency for purchase reconciliation.',
    '先准备采购账单列表和供应商对账资料，确定要核对的供应商及币种。' => 'Prepare the purchase bill list and vendor reconciliation records, identifying the vendors and currencies to check.',
    '逐行查看供应商和币种分组，核对账单金额、合计及港币折算口径。' => 'Review each vendor and currency group, checking bill amounts, totals, and the HKD conversion basis.',
    '把异常供应商或币种与账单、贷记单和付款核销记录交叉检查。' => 'Cross-check unusual vendors or currencies against bills, credit notes, and payment allocations.',
    '确认合计后使用页头「导出 PDF」，选择语言保存采购明细。' => 'After verifying the totals, use Export PDF in the header and choose a language to save the purchase detail.',
    '供应商及币种合计能与账单和贷记单记录勾稽，PDF 与页面数字一致。' => 'Vendor and currency totals reconcile to bill and credit-note records, and PDF figures match the page.',
    '当前实现未把上方起止日期传给采购报表接口，不要当作已按期间筛选；采购额不等于已付款。' => 'The current implementation does not pass the dates above to the purchase report interface, so results are not period-filtered. Purchases do not equal payments.',

    // Inline help: audit through search
    '审计探索器：只读追查分录、来源、反向关系和导出文件哈希。' => 'Audit explorer: trace entries, sources, reversal relationships, and exported file hashes read-only.',
    '先在「搜索分录号 / 摘要 / 来源」输入条件并点「搜索」，需要时点每页条数或「应用」。' => 'Enter criteria under Search entry no. / description / source and select Search. Change rows per page or select Apply when needed.',
    '查看顶部「哈希链」是否完整及检查条数，异常时保留提示并停止依赖相关导出。' => 'Check Hash chain integrity and the number of records checked at the top. For exceptions, retain the warning and stop relying on related exports.',
    '点目标行「下钻」，逐行核对科目、来源类型、源单 ID、原币和汇率，并查看冲销关系。' => 'Select Drill down on the target row, check each account, source type, source document ID, original currency, and exchange rate, and review reversal relationships.',
    '需要证据时点「导出（带哈希）」，在最近导出中下载并核对 SHA-256；不再需要的文件才点「删除」。' => 'For evidence, select Export (with hash), download from Recent exports, and verify SHA-256. Delete only files no longer needed.',
    '目标分录能追到来源与反向关系，哈希链完整，下载文件的 SHA-256 与记录一致。' => 'The target entry traces to its source and reversal relationship, the hash chain is intact, and the downloaded file SHA-256 matches the record.',
    '审计分录只读；删除导出文件不可恢复，但导出审计记录仍保留，哈希链异常不要自行忽略。' => 'Audit entries are read-only. Export file deletion is irreversible, although export audit records remain. Never ignore hash-chain exceptions.',
    '开源许可证：查看 Lt-AI-Books 的版权方、MIT 授权范围和保留声明要求。' => 'Open-source license: review the Lt-AI-Books copyright holder, MIT license scope, and notice retention requirements.',
    '先确认当前软件名称、版本、版权方和年份，明确自己是使用、修改还是再分发。' => 'Confirm the current software name, version, copyright holder, and year, and identify whether you are using, modifying, or redistributing it.',
    '阅读「授权概要」，了解允许使用、复制、修改、分发和商用的范围。' => 'Read License summary to understand the permissions for use, copying, modification, distribution, and commercial use.',
    '重点检查保留版权声明与许可声明的条件，以及软件按「现状」提供的说明。' => 'Focus on the requirement to retain copyright and license notices and the statement that the software is provided as is.',
    '需要对外分发时阅读「许可证全文」，把完整 MIT 文本随软件一起保留。' => 'For external distribution, read Full license text and retain the complete MIT text with the software.',
    '你能说明使用权限和再分发条件，并确认分发副本保留完整版权与许可文本。' => 'You can explain usage permissions and redistribution conditions, and distributed copies retain the complete copyright and license text.',
    'MIT 许可允许广泛使用后仍要求保留声明；本页是许可证信息，不是针对具体商业安排的法律意见。' => 'The MIT license permits broad use but still requires notice retention. This page provides license information, not legal advice for a specific commercial arrangement.',
    '备份与恢复：管理员创建、下载和安排备份，并在明确确认后恢复数据。' => 'Backup and restore: administrators create, download, and schedule backups, then restore data after explicit confirmation.',
    '先确认当前账套和附件可正常访问，并准备足够磁盘空间；自动备份时间按香港时间填写。' => 'Confirm the current ledger and attachments are accessible and sufficient disk space is available. Enter automatic backup times in Hong Kong time.',
    '手动全量备份点「立即创建完整备份」；自动备份填写最多四个时间后点「保存自动备份时间」。' => 'For a manual full backup, select Create full backup now. For automatic backups, enter up to four times and select Save automatic backup times.',
    '在备份列表核对文件名、类型、大小和时间，点击「下载」保存一份到独立安全位置。' => 'Check each backup filename, type, size, and time in the list, then Download a copy to a separate secure location.',
    '需要恢复时选择已有备份点「恢复所选备份」，或点「上传并恢复」选择不超过 512MB 的 .tar.gz 文件。' => 'To restore, choose an existing backup and select Restore selected backup, or select Upload and restore and choose a .tar.gz file no larger than 512 MB.',
    '勾选要恢复的数据库或附件，明确勾选覆盖确认；完成后登录核对账套、单据和附件，并保留自动创建的安全备份。' => 'Select the database or attachments to restore and explicitly confirm overwriting. Afterward, sign in to verify the ledger, documents, and attachments, and retain the automatic safety backup.',
    '新备份出现在列表且可下载；恢复后数据与所选备份时点一致，并能找到恢复前的安全备份。' => 'The new backup appears in the list and downloads successfully. Restored data matches the selected backup point, and the pre-restore safety backup is available.',
    '恢复会覆盖现有数据库或附件，删除备份也不可恢复；手动备份为完整备份、自动备份在同一文件上滚动更新，操作前务必先下载独立副本。' => 'Restore overwrites the current database or attachments, and backup deletion is irreversible. Manual backups are full and automatic backups roll into one file; download a separate copy before either operation.',
    '邮件：配置 SMTP、测试发信，并把报价单或业务单据 PDF 发给收件人。' => 'Email: configure SMTP, test sending, and email quotation or business document PDFs to recipients.',
    '先准备收件人邮箱和要发送的单据；管理员同时准备 SMTP 主机、端口、加密方式、账号及授权码。' => 'Prepare recipient addresses and the document to send. Administrators also need the SMTP host, port, encryption, account, and authorization code.',
    '管理员填写发信服务器、端口、加密、账号、密码或授权码及发件人名称，点「保存 SMTP 设置」。' => 'The administrator enters the outgoing server, port, encryption, account, password or authorization code, and sender name, then selects Save SMTP settings.',
    '点「发送测试邮件」，确认测试收件箱能收到且发件人显示正确。' => 'Select Send test email and confirm the test inbox receives it with the correct sender display.',
    '从单据进入邮件页，填写「收件人」「抄送」「主题」「正文（可选）」，先点「预览 PDF」核对内容。' => 'Open Email from a document, enter To, CC, Subject, and Body (optional), then Preview PDF to verify its contents.',
    '确认附件与收件人后点「发送（附 PDF）」，在发送记录中查看成功或失败结果。' => 'After confirming the attachment and recipients, select Send (with PDF) and check the sending log for success or failure.',
    '测试及正式发送记录显示成功，收件人收到的主题、正文和 PDF 与预览一致。' => 'Test and production sending logs show success, and recipients receive the subject, body, and PDF matching the preview.',
    'SMTP 通常使用授权码而非登录密码；发送后无法从系统撤回邮件，抄送和外部收件人必须在发送前反复核对。' => 'SMTP usually uses an authorization code rather than the login password. Sent email cannot be recalled through the system; carefully recheck CC and external recipients before sending.',
    '公司资料：维护单据抬头、财务年度、报告框架、Logo 和主收款账户。' => 'Company profile: maintain document headings, financial year, reporting framework, logo, and primary receiving account.',
    '先准备商业登记证、注册地址、年结日、报告框架和银行开户文件。' => 'Prepare the business registration certificate, registered address, financial year-end, reporting framework, and bank account documents.',
    '管理员在「编辑公司档案」填写公司名称、法定名称、中文名称、登记号、地址及联系方式。' => 'Under Edit company profile, the administrator enters the company name, legal name, Chinese name, registration number, address, and contact details.',
    '选择「财务年度年结日」「报告框架」，填写主收款账户资料后点「保存公司档案」。' => 'Select Financial year-end and Reporting framework, enter the primary receiving account details, then Save company profile.',
    '需要更换标识时在「公司 Logo」点「选择文件」并「上传并替换」；需要还原时点「恢复内置 Logo」。' => 'To change the logo, select Choose file under Company Logo, then Upload and replace. To revert, select Restore built-in logo.',
    '点「生成抬头纸」并打开一张销售发票 PDF，核对公司名称、地址、Logo 和收款账户。' => 'Select Generate letterhead and open a sales invoice PDF to verify the company name, address, logo, and receiving account.',
    '公司档案保存成功，抬头纸和发票 PDF 显示最新合法资料及正确银行信息。' => 'The company profile saves successfully, and letterhead and invoice PDFs show the current legal details and correct bank information.',
    '年结日和报告框架会改变报表口径；银行账户会印在发票上，Logo 替换会全站生效，修改前必须与法定及开户文件核对。' => 'Year-end and reporting framework change report bases. Bank accounts appear on invoices, and logo replacement applies site-wide; verify changes against legal and bank documents first.',
    '账号：修改自己的口令和使用模式，管理员还可维护税务资格与用户。' => 'Account: change your password and working mode; administrators can also maintain tax eligibility and users.',
    '先核对「当前账号」和角色，在「AI 模式」或「人工模式」卡片中选择适合自己的工作方式。' => 'Check Current account and role, then choose the appropriate working style on the AI mode or Manual mode card.',
    '修改登录凭据时填写「原口令」和「新口令（至少 10 位）」，再点「修改口令」。' => 'To change login credentials, enter Current password and New password (at least 10 characters), then Change password.',
    '管理员处理税务事实时选择两级制状态、填写「依据」并点「更新资格」。' => 'To record tax facts, the administrator selects the two-tier status, enters Basis, and selects Update eligibility.',
    '管理员添加人员时填写「用户名」「显示名」「初始口令」「角色」，核对权限后点「新建用户」。' => 'To add a person, the administrator enters Username, Display name, Initial password, and Role, checks permissions, then Create user.',
    '用新口令重新登录或让新用户登录，检查模式、角色和可访问页面是否正确。' => 'Sign in again with the new password or have the new user sign in, then check the mode, role, and accessible pages.',
    '新口令可正常登录，使用模式已切换；新用户和税务资格显示预期状态。' => 'The new password works, the working mode has changed, and the new user and tax eligibility show the expected statuses.',
    '口令不要与他人共用或通过聊天外发；角色会决定可见及可写功能，税务资格变更会影响税额并留下审计记录。' => 'Never share passwords or send them through chat. Roles determine visible and writable functions, and tax eligibility changes affect tax amounts and leave an audit record.',
    '全局搜索：用编号或银行参考号快速找到发票、账单、分录和流水。' => 'Global search: quickly find invoices, bills, entries, and bank transactions by number or bank reference.',
    '先准备尽量完整的业务编号或银行参考号，并确认大致单据类型。' => 'Prepare the most complete business number or bank reference available and identify the likely document type.',
    '在顶部搜索框输入关键词，提交后查看匹配结果数量。' => 'Enter keywords in the top search box, submit, and review the number of matches.',
    '按结果类型、编号、日期、往来单位和摘要排除不相关记录。' => 'Use result type, number, date, counterparty, and description to exclude irrelevant records.',
    '点目标行的「打开」，进入详情后再核对金额、状态和关联凭证。' => 'Select Open on the target row, then verify the amount, status, and linked vouchers in its details.',
    '搜索结果与输入编号相符，并能通过「打开」到达正确单据或流水详情。' => 'Search results match the entered number, and Open leads to the correct document or transaction details.',
    '搜索主要覆盖发票、账单、分录和银行参考号，不是全文 OCR；搜不到时检查空格和编号，再到对应列表按客户或供应商查询。' => 'Search mainly covers invoices, bills, entries, and bank references, not full-text OCR. If nothing is found, check spaces and numbers, then search the relevant list by customer or vendor.',
    '+ 新增银行账户' => '+ Add bank account',
    '+ 新建规则' => '+ New rule',
    '「执行一次」按下次执行日建单，并把下次执行日往后推一期' => 'Run once creates a document on the next run date and moves that date forward one period',
    '上传时已记 SHA-256，改动可查 · 单文件上限 20MB' => 'SHA-256 is recorded on upload so changes can be traced · Maximum 20MB per file',
