    '暂无已过账采购发票' => 'No posted purchase invoices yet',
    '暂无已过账销售发票' => 'No posted sales invoices yet',
    '没有逾期应收' => 'No overdue receivables',
    '现金覆盖与回款节奏处于可控区间。' => 'Cash coverage and collection timing are within a manageable range.',
    '经常性账单及费用' => 'Recurring bills and expenses',
    '记账分录' => 'Journal entry',
    '费用信息' => 'Expense details',
    '选填；保存后会显示在费用列表和详情，可用于搜索' => 'Optional; after saving, it appears in the expense list and details and can be used in searches',
    '冰川青' => 'Glacier Teal',
    '午夜靛蓝' => 'Midnight Indigo',
    '石墨夜色' => 'Graphite Night',
    '赤陶暖棕' => 'Terracotta',
    '冷灰蓝、白卡片，层级最清楚；适合日常录入与报表展示' => 'Cool grey-blue with white cards for the clearest hierarchy; suitable for daily entry and report presentation',
    '清透青灰底与深青主色，冷静利落；适合票据核对与数据分析' => 'A clear blue-grey background and deep teal accents; suitable for checking documents and analysing data',
    '暖白账页与赤陶主色，辅以橄榄绿；适合审阅凭证与管理层报表' => 'Warm-white ledger pages with terracotta accents and olive green; suitable for reviewing vouchers and management reports',
    '中性石墨灰与高亮正文，蓝色操作聚焦；底色不再压到纯黑，长时间阅读更稳' => 'Neutral graphite grey with high-contrast body text and blue focus states; the background is not pure black, making extended reading more comfortable',
    '靛蓝底与柔和紫光点缀，和石墨灰明确区分；适合夜间结账与复核' => 'An indigo background with soft violet accents, clearly distinct from graphite grey; suitable for night-time closing and review',
    '收入合计' => 'Total income',
